function whatsappUrl(message) {
  return `https://wa.me/${APP_CONFIG.whatsappNumber}?text=${encodeURIComponent(message)}`;
}

function renderConfig() {
  document.querySelectorAll('[data-config="name"]').forEach((el) => { el.textContent = APP_CONFIG.name; });
  document.querySelectorAll('[data-config="location"]').forEach((el) => { el.textContent = APP_CONFIG.location; });
  document.querySelectorAll('[data-config="reference"]').forEach((el) => { el.textContent = APP_CONFIG.reference; });
  document.querySelectorAll('[data-maps-link]').forEach((el) => {
    el.href = APP_CONFIG.mapsUrl === '#' ? '#ubicacion' : APP_CONFIG.mapsUrl;
    el.title = APP_CONFIG.mapsUrl === '#' ? 'Enlace de mapa por configurar' : 'Abrir ubicación en el mapa';
  });
}

function renderServices() {
  const grid = document.querySelector('#services-grid');
  if (!grid) return;
  grid.innerHTML = APP_CONFIG.services.map(([title, description, icon], index) => `
    <article class="service-card reveal">
      <span class="service-index">0${index + 1}</span>
      <span class="service-icon">${icons[icon] || icons.plus}</span>
      <h3>${title}</h3>
      <p>${description}</p>
      <span class="service-arrow">↗</span>
    </article>
  `).join('');
}

function renderHours() {
  const list = document.querySelector('#hours-list');
  if (!list) return;
  list.innerHTML = APP_CONFIG.hours.map(([day, time]) => `<div class="hours-row"><span>${day}</span><span>${time}</span></div>`).join('');
  const footerHours = document.querySelector('#footer-hours');
  if (footerHours) footerHours.innerHTML = APP_CONFIG.hours.map(([day, time]) => `<span class="footer-hours-line">${day}: ${time}</span>`).join('');
}

function bindWhatsApp() {
  document.querySelectorAll('[data-whatsapp], .js-whatsapp').forEach((link) => {
    link.addEventListener('click', (event) => {
      event.preventDefault();
      const message = link.dataset.message || 'Hola, quisiera solicitar información.';
      window.open(whatsappUrl(message), '_blank', 'noopener,noreferrer');
    });
  });
}

function saveWebLead(lead) {
  try {
    const current = JSON.parse(localStorage.getItem('pd-054-leads-v1') || '[]');
    localStorage.setItem('pd-054-leads-v1', JSON.stringify([lead, ...current.filter((item) => item.id !== lead.id)].slice(0, 50)));
  } catch (error) {
    // La demo continúa aunque el navegador no permita almacenamiento local.
  }
}

function bindForm() {
  const form = document.querySelector('#demo-form');
  const status = document.querySelector('#form-status');
  if (!form || !status) return;
  form.addEventListener('submit', (event) => {
    event.preventDefault();
    if (!form.reportValidity()) return;
    const data = new FormData(form);
    const message = [
      'Hola, quisiera solicitar información sobre el servicio automotriz.', '',
      `Nombre: ${data.get('name')}`, `Teléfono: ${data.get('phone')}`,
      `Ubicación: ${data.get('location') || 'Por confirmar'}`, `Vehículo: ${data.get('vehicle') || 'Por confirmar'}`,
      `Servicio: ${data.get('service')}`, `Observaciones: ${data.get('notes') || 'Sin observaciones'}`
    ].join('\n');
    status.textContent = 'Solicitud preparada. Abriendo WhatsApp…';
    window.open(whatsappUrl(message), '_blank', 'noopener,noreferrer');
    form.reset();
  });
}

function bindMobileMenu() {
  const button = document.querySelector('.menu-toggle');
  const links = document.querySelector('#nav-links');
  if (!button || !links) return;
  button.addEventListener('click', () => {
    const open = links.classList.toggle('open');
    button.setAttribute('aria-expanded', String(open));
  });
  links.querySelectorAll('a').forEach((link) => link.addEventListener('click', () => {
    links.classList.remove('open');
    button.setAttribute('aria-expanded', 'false');
  }));
}

function bindReveal() {
  const items = document.querySelectorAll('.reveal');
  if (!('IntersectionObserver' in window)) { items.forEach((item) => item.classList.add('visible')); return; }
  const observer = new IntersectionObserver((entries) => {
    entries.forEach((entry) => {
      if (entry.isIntersecting) { entry.target.classList.add('visible'); observer.unobserve(entry.target); }
    });
  }, { threshold: 0.12 });
  items.forEach((item, index) => { item.style.transitionDelay = `${Math.min(index % 4, 3) * 55}ms`; observer.observe(item); });
}

function initChatbot() {
  const root = document.createElement('div');
  root.className = 'demo-chat';
  root.innerHTML = `
    <button class="demo-chat-launch" type="button" aria-expanded="false" aria-controls="demo-chat-panel"><span class="demo-chat-launch-icon">✦</span><span class="demo-chat-launch-label">Asistente demo</span></button>
    <section class="demo-chat-panel" id="demo-chat-panel" aria-label="Chatbot de demostración" hidden>
      <header class="demo-chat-head"><div><span class="demo-chat-kicker">CHATBOT / DEMO</span><strong>Cuéntanos sobre tu vehículo</strong></div><button type="button" data-chat-close aria-label="Cerrar chatbot">×</button></header>
      <div class="demo-chat-notice">Información ficticia para validar el recorrido. No se almacena en un sistema productivo.</div>
      <div class="demo-chat-messages" data-chat-messages></div><form class="demo-chat-form" data-chat-form></form>
    </section>`;
  document.body.appendChild(root);
  const launch = root.querySelector('.demo-chat-launch'); const panel = root.querySelector('.demo-chat-panel'); const messages = root.querySelector('[data-chat-messages]'); const form = root.querySelector('[data-chat-form]');
  const fields = [
    { key: 'name', question: '¿Cómo te llamas?', type: 'text', placeholder: 'Tu nombre', required: true },
    { key: 'phone', question: '¿Cuál es tu teléfono?', type: 'tel', placeholder: 'Ej. 5550 0000', required: true },
    { key: 'email', question: '¿Tienes un correo? Es opcional.', type: 'email', placeholder: 'correo@ejemplo.com' },
    { key: 'vehicle', question: '¿Qué vehículo necesitas revisar? Marca, modelo y año.', type: 'text', placeholder: 'Ej. Toyota Corolla 2018', required: true },
    { key: 'service', question: '¿Qué servicio necesitas?', type: 'select', options: ['Diagnóstico general', 'Servicio preventivo', 'Frenos', 'Suspensión', 'Sistema eléctrico', 'Otro servicio'], required: true },
    { key: 'description', question: 'Cuéntanos brevemente qué sucede.', type: 'textarea', placeholder: 'Describe el síntoma o lo que necesitas…', required: true },
    { key: 'channel', question: '¿Por qué medio prefieres que te contactemos?', type: 'select', options: ['WhatsApp', 'Llamada', 'Correo'], required: true }
  ];
  const state = { step: 0, answers: {}, started: false };
  const addMessage = (text, from = 'bot') => { const item = document.createElement('div'); item.className = `demo-chat-message ${from}`; item.textContent = text; messages.appendChild(item); messages.scrollTop = messages.scrollHeight; };
  const renderStep = () => { const field = fields[state.step]; if (!field) return; addMessage(field.question, 'bot'); let control = ''; if (field.type === 'select') control = `<select name="${field.key}" required><option value="" selected disabled>Selecciona una opción</option>${field.options.map((option) => `<option>${option}</option>`).join('')}</select>`; else if (field.type === 'textarea') control = `<textarea name="${field.key}" rows="2" placeholder="${field.placeholder}" ${field.required ? 'required' : ''}></textarea>`; else control = `<input name="${field.key}" type="${field.type}" placeholder="${field.placeholder}" ${field.required ? 'required' : ''} />`; form.innerHTML = `<label class="sr-only" for="chat-field">${field.question}</label>${control}<button class="demo-chat-send" type="submit">Continuar <span>↗</span></button>`; const input = form.querySelector('input, select, textarea'); input.id = 'chat-field'; input.focus(); };
  const close = () => { panel.hidden = true; launch.setAttribute('aria-expanded', 'false'); launch.classList.remove('is-open'); };
  const open = () => { panel.hidden = false; launch.setAttribute('aria-expanded', 'true'); launch.classList.add('is-open'); if (!state.started) { state.started = true; addMessage('Hola. Soy el asistente de esta demo. Te haré unas preguntas para crear una solicitud de ejemplo.'); renderStep(); } };
  launch.addEventListener('click', () => panel.hidden ? open() : close()); root.querySelector('[data-chat-close]').addEventListener('click', close);
  form.addEventListener('submit', (event) => { event.preventDefault(); const data = new FormData(form); const field = fields[state.step]; const value = String(data.get(field.key) || '').trim(); if (field.required && !value) { form.querySelector('input, select, textarea').focus(); return; } state.answers[field.key] = value; addMessage(value || 'Por confirmar', 'user'); state.step += 1; if (state.step < fields.length) renderStep(); else { const lead = { id: `CHAT-${Date.now().toString().slice(-6)}`, name: state.answers.name, phone: state.answers.phone, email: state.answers.email || 'No proporcionado', vehicle: state.answers.vehicle, service: state.answers.service, description: state.answers.description, channel: state.answers.channel, date: new Date().toLocaleDateString('es-GT', { day: '2-digit', month: 'short', year: 'numeric' }).replace('.', ''), source: 'Chatbot web', status: 'nuevo', notes: 'Lead creado desde el chatbot de demostración.' }; saveWebLead(lead); addMessage('¡Listo! Recibimos tu solicitud de demostración. Ventas puede verla y contactarte desde el panel interno.', 'bot'); form.innerHTML = `<div class="demo-chat-confirm"><span>✓</span><strong>Solicitud recibida</strong><small>ID ${lead.id} · Datos de demostración</small><a href="/crm">Abrir panel de Ventas</a><button type="button" data-chat-restart>Crear otra solicitud</button></div>`; form.querySelector('[data-chat-restart]').addEventListener('click', () => { state.step = 0; state.answers = {}; messages.innerHTML = ''; renderStep(); }); } });
}

const isCrmRoute = () => window.location.pathname === '/crm' || window.location.pathname.startsWith('/crm/');
