function cloneDemo(value) { return JSON.parse(JSON.stringify(value)); }
function crmEsc(value) { return String(value ?? '').replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#039;' }[char])); }
function crmAmount(value) { return `Q ${Number(value || 0).toLocaleString('es-GT', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`; }
function crmDate() { return new Date().toLocaleDateString('es-GT', { day: '2-digit', month: 'short', year: 'numeric' }).replace('.', ''); }
function crmTime() { return new Date().toLocaleTimeString('es-GT', { hour: '2-digit', minute: '2-digit' }); }
function crmClient(id) { return crmState.clients.find((client) => client.id === id) || { id: '—', name: 'Cliente por seleccionar', phone: '—', email: '—', vehicle: 'Vehículo por seleccionar', year: '—', plate: '—' }; }
function crmQuote(id) { return crmState.quotes.find((quote) => quote.id === id); }
function crmOrder(id) { return crmState.orders.find((order) => order.id === id); }
function crmStatus(status) { return CRM_STATUS_LABELS[status] || status; }
function crmStatusClass(status) { return `pdcrm-status-${String(status || '').replace(/_/g, '-')}`; }
function quoteTotals(quote) { const subtotal = (quote.items || []).reduce((sum, item) => sum + (Number(item.quantity) || 0) * (Number(item.price) || 0), 0); const discount = Number(quote.discount) || 0; const taxable = Math.max(0, subtotal - discount); const tax = taxable * ((Number(quote.taxRate) || 0) / 100); return { subtotal, discount, tax, total: taxable + tax }; }
function crmIcon(name, size = 18) { const paths = { grid: '<rect x="3" y="3" width="6" height="6" rx="1"/><rect x="15" y="3" width="6" height="6" rx="1"/><rect x="3" y="15" width="6" height="6" rx="1"/><rect x="15" y="15" width="6" height="6" rx="1"/>', users: '<path d="M16 20v-1.5a3.5 3.5 0 0 0-3.5-3.5h-5A3.5 3.5 0 0 0 4 18.5V20"/><circle cx="10" cy="8" r="3"/><path d="M17 11a3 3 0 1 0 0-6M20 20v-1.4a3.5 3.5 0 0 0-2.5-3.35"/>', user: '<circle cx="12" cy="8" r="3"/><path d="M5 20a7 7 0 0 1 14 0"/>', quote: '<path d="M5 4h14a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2Z"/><path d="M7 8h10M7 12h7M7 16h4"/>', order: '<path d="M4 7h16M7 4v6M17 4v6M5 4h14a1 1 0 0 1 1 1v15H4V5a1 1 0 0 1 1-1Z"/><path d="m8 15 2 2 5-5"/>', arrow: '<path d="M5 12h13M13 6l6 6-6 6"/>', back: '<path d="M19 12H5M11 18l-6-6 6-6"/>', plus: '<path d="M12 5v14M5 12h14"/>', search: '<circle cx="10.8" cy="10.8" r="6.8"/><path d="m16 16 4 4"/>', more: '<circle cx="5" cy="12" r="1" fill="currentColor" stroke="none"/><circle cx="12" cy="12" r="1" fill="currentColor" stroke="none"/><circle cx="19" cy="12" r="1" fill="currentColor" stroke="none"/>', filter: '<path d="M4 6h16M7 12h10M10 18h4"/>', trend: '<path d="m4 16 5-5 3 3 7-8"/><path d="M15 6h4v4"/>', wallet: '<path d="M4 6.5A2.5 2.5 0 0 1 6.5 4H19a1 1 0 0 1 1 1v15H6.5A2.5 2.5 0 0 1 4 17.5z"/><path d="M4 7h14M16 13h4"/><circle cx="16" cy="13" r=".7" fill="currentColor" stroke="none"/>', receipt: '<path d="M6 3h12v18l-3-2-3 2-3-2-3 2z"/><path d="M9 8h6M9 12h6M9 16h3"/>', car: '<path d="m5 16 1.8-5.4A2.5 2.5 0 0 1 9.2 9h5.6a2.5 2.5 0 0 1 2.4 1.6L19 16v4H5z"/><path d="M6 15h12M8 19h.01M16 19h.01"/>', wrench: '<path d="m16 8 2 2-6.6 6.6a3 3 0 1 1-4-4L14 6"/><path d="m17 5 2-2 2 2-2 2M8 15l-4 4"/>', settings: '<circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.7 1.7 0 0 0 .34 1.88l.06.06-1.7 1.7-.06-.06a1.7 1.7 0 0 0-1.88-.34 1.7 1.7 0 0 0-1.04 1.56V20h-2.4v-.2a1.7 1.7 0 0 0-1.04-1.56 1.7 1.7 0 0 0-1.88.34l-.06.06-1.7-1.7.06-.06A1.7 1.7 0 0 0 8.4 15a1.7 1.7 0 0 0-1.56-1.04H6v-2.4h.84A1.7 1.7 0 0 0 8.4 10a1.7 1.7 0 0 0-.34-1.88L8 8.06l1.7-1.7.06.06A1.7 1.7 0 0 0 11.64 6.1 1.7 1.7 0 0 0 12.68 4.5V4h2.4v.5a1.7 1.7 0 0 0 1.04 1.56 1.7 1.7 0 0 0 1.88-.34l.06-.06 1.7 1.7-.06.06A1.7 1.7 0 0 0 19.4 9a1.7 1.7 0 0 0 1.56 1.04h.04v2.4h-.04A1.7 1.7 0 0 0 19.4 15Z"/>', help: '<circle cx="12" cy="12" r="9"/><path d="M9.5 9a2.6 2.6 0 1 1 4.5 1.8c-1.4 1.2-2 1.5-2 3.2M12 17h.01"/>', check: '<path d="m5 12 4 4L19 6"/>', close: '<path d="m6 6 12 12M18 6 6 18"/>', menu: '<path d="M4 7h16M4 12h16M4 17h16"/>', eye: '<path d="M2.5 12s3.2-5 9.5-5 9.5 5 9.5 5-3.2 5-9.5 5-9.5-5-9.5-5Z"/><circle cx="12" cy="12" r="2"/>', download: '<path d="M12 3v12M7 10l5 5 5-5M5 20h14"/>', refresh: '<path d="M20 11a8 8 0 0 0-14.5-4L4 9"/><path d="M4 4v5h5M4 13a8 8 0 0 0 14.5 4L20 15"/><path d="M20 20v-5h-5"/>', clock: '<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>', alert: '<path d="M12 3 2.8 19h18.4z"/><path d="M12 9v4M12 16h.01"/>', external: '<path d="M14 4h6v6M20 4l-9 9"/><path d="M18 13v5a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h5"/>', camera: '<path d="M4 8h4l1.5-2h5L16 8h4v11H4z"/><circle cx="12" cy="13" r="3"/>', file: '<path d="M6 3h8l4 4v14H6z"/><path d="M14 3v5h5M9 13h6M9 17h6"/>', phone: '<path d="M6 4h3l1.5 4-2 1.5a14 14 0 0 0 6 6l1.5-2 4 1.5v3a2 2 0 0 1-2 2C10 19 5 14 5 6a2 2 0 0 1 1-2 2Z"/>' }; return `<svg class="pdcrm-icon" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name] || paths.grid}</svg>`; }
function loadJson(key, fallback) { try { const value = JSON.parse(localStorage.getItem(key)); return value || cloneDemo(fallback); } catch (error) { return cloneDemo(fallback); } }
function saveJson(key, value) { try { localStorage.setItem(key, JSON.stringify(value)); } catch (error) { /* Demo fallback */ } }
function loadCrmState() { const old = loadJson('pd-054-crm-demo-v1', {}); const saved = loadJson(CRM_STATE_KEY, old); return { ...cloneDemo(CRM_DEFAULT_STATE), ...saved }; }
function saveCrmState() { saveJson(CRM_STATE_KEY, crmState); }
function loadLeads() { return loadJson(CRM_LEADS_KEY, CRM_LEADS_DEFAULT); }
function saveLeads(leads) { saveJson(CRM_LEADS_KEY, leads); }
function loadSession() { try { return JSON.parse(localStorage.getItem(CRM_SESSION_KEY)); } catch (error) { return null; } }
function saveSession(session) { if (session) saveJson(CRM_SESSION_KEY, session); else { try { localStorage.removeItem(CRM_SESSION_KEY); } catch (error) { /* Demo fallback */ } } }
function crmLeads() { return loadLeads(); }
function addActivity(icon, title, detail, route = '/crm') { crmState.activity.unshift({ icon, title, detail, route }); crmState.activity = crmState.activity.slice(0, 20); }

const ROLE_NAV = {
  admin: [{ label: 'Resumen', href: '/crm/admin', icon: 'grid', view: 'admin-dashboard' }, { label: 'Recepción de vehículos', href: '/crm/admin/recepciones', icon: 'car', view: 'receptions' }, { label: 'Clientes y vehículos', href: '/crm/clientes', icon: 'users', view: 'clients' }, { label: 'Cotizaciones', href: '/crm/cotizaciones', icon: 'quote', view: 'quotes' }, { label: 'Órdenes de servicio', href: '/crm/ordenes', icon: 'order', view: 'orders' }, { label: 'Servicios y mantenimientos', href: '/crm/admin/servicios', icon: 'wrench', view: 'services' }, { label: 'Seguimientos', href: '/crm/admin/seguimientos', icon: 'clock', view: 'followups' }, { label: 'Cuentas por cobrar', href: '/crm/cobrar', icon: 'wallet', view: 'receivables' }, { label: 'Cuentas por pagar', href: '/crm/pagar', icon: 'receipt', view: 'payables' }, { label: 'Documentos y PDFs', href: '/crm/admin/documentos', icon: 'file', view: 'documents' }, { label: 'Usuarios y permisos', href: '/crm/admin/usuarios', icon: 'users', view: 'users' }, { label: 'Configuración', href: '/crm/admin/configuracion', icon: 'settings', view: 'settings' }],
  recolector: [{ label: 'Inicio', href: '/crm/recolector', icon: 'grid', view: 'collector-dashboard' }, { label: 'Nueva recepción', href: '/crm/recolector/nueva-recepcion', icon: 'plus', view: 'new-reception' }, { label: 'Mis recepciones', href: '/crm/recolector/recepciones', icon: 'car', view: 'collector-receptions' }, { label: 'Vehículos asignados', href: '/crm/recolector/vehiculos', icon: 'order', view: 'assigned-vehicles' }, { label: 'Evidencias', href: '/crm/recolector/evidencias', icon: 'camera', view: 'evidence' }, { label: 'Historial', href: '/crm/recolector/historial', icon: 'clock', view: 'history' }],
  ventas: [{ label: 'Resumen', href: '/crm/ventas', icon: 'grid', view: 'sales-dashboard' }, { label: 'Leads de la página web', href: '/crm/ventas/leads-web', icon: 'external', view: 'leads-web' }, { label: 'Leads del chatbot', href: '/crm/ventas/leads-chatbot', icon: 'phone', view: 'leads-chatbot' }, { label: 'Clientes', href: '/crm/ventas/clientes', icon: 'users', view: 'sales-clients' }, { label: 'Cotizaciones', href: '/crm/ventas/cotizaciones', icon: 'quote', view: 'sales-quotes' }, { label: 'Seguimientos', href: '/crm/ventas/seguimientos', icon: 'clock', view: 'sales-followups' }, { label: 'Oportunidades', href: '/crm/ventas/oportunidades', icon: 'trend', view: 'opportunities' }, { label: 'Comunicaciones', href: '/crm/ventas/comunicaciones', icon: 'phone', view: 'communications' }]
};
function defaultRouteForRole(role) { return role === 'admin' ? '/crm/admin' : role === 'ventas' ? '/crm/ventas' : '/crm/recolector'; }
function routeView(path) { const clean = path.replace(/\/+$/, '') || '/crm'; if (clean === '/crm') return { view: 'home' }; if (clean === '/crm/admin') return { view: 'admin-dashboard', role: 'admin' }; if (clean.startsWith('/crm/admin/')) { const segment = clean.split('/')[3]; const map = { recepciones: 'receptions', servicios: 'services', seguimientos: 'followups', documentos: 'documents', usuarios: 'users', configuracion: 'settings' }; return { view: map[segment] || 'unknown', role: 'admin' }; } if (clean === '/crm/recolector') return { view: 'collector-dashboard', role: 'recolector' }; if (clean.startsWith('/crm/recolector/')) { const segment = clean.split('/')[3]; const map = { 'nueva-recepcion': 'new-reception', recepciones: 'collector-receptions', vehiculos: 'assigned-vehicles', evidencias: 'evidence', historial: 'history' }; return { view: map[segment] || 'unknown', role: 'recolector' }; } if (clean === '/crm/ventas') return { view: 'sales-dashboard', role: 'ventas' }; if (clean.startsWith('/crm/ventas/')) { const parts = clean.split('/').filter(Boolean).slice(2); const segment = parts[0]; if (segment === 'leads-web' || segment === 'leads-chatbot') return parts[1] ? { view: 'lead-detail', role: 'ventas', id: parts[1], source: segment === 'leads-chatbot' ? 'Chatbot web' : 'Página web' } : { view: segment, role: 'ventas' }; if (segment === 'cotizaciones') return parts[1] === 'nueva' ? { view: 'quote-new', role: 'ventas' } : parts[1] ? { view: parts[2] === 'edit' ? 'quote-edit' : 'quote-detail', role: 'ventas', id: parts[1] } : { view: 'sales-quotes', role: 'ventas' }; const map = { clientes: 'sales-clients', seguimientos: 'sales-followups', oportunidades: 'opportunities', comunicaciones: 'communications' }; return { view: map[segment] || 'unknown', role: 'ventas' }; } if (clean === '/crm/clientes') return { view: 'clients', role: 'admin' }; if (clean === '/crm/cotizaciones') return { view: 'quotes', role: 'admin' }; if (clean.startsWith('/crm/cotizaciones/')) { const parts = clean.split('/').filter(Boolean); return parts[2] === 'nueva' ? { view: 'quote-new', role: 'admin' } : { view: parts[3] === 'edit' ? 'quote-edit' : 'quote-detail', role: 'admin', id: parts[2] }; } if (clean === '/crm/ordenes') return { view: 'orders', role: 'admin' }; if (clean.startsWith('/crm/ordenes/')) { const parts = clean.split('/').filter(Boolean); return parts[2] === 'nueva' ? { view: 'order-new', role: 'admin' } : { view: 'order-detail', role: 'admin', id: parts[2] }; } if (clean === '/crm/cobrar') return { view: 'receivables', role: 'admin' }; if (clean === '/crm/pagar') return { view: 'payables', role: 'admin' }; return { view: 'unknown' }; }
function canAccessRoute(route) { if (route.view === 'home') return true; if (['quote-new', 'quote-edit', 'quote-detail', 'order-detail'].includes(route.view)) return ['admin', 'ventas'].includes(crmSession.role); if (route.role && route.role !== crmSession.role) return false; return route.view !== 'unknown'; }

function loginView() { return `<main class="pdcrm-login"><div class="pdcrm-login-art"><div class="pdcrm-login-art-inner"><span class="pdcrm-login-mark">${crmIcon('car', 30)}</span><span class="pdcrm-kicker">PD-054 · TALLER AUTOMOTRIZ</span><h1>Una operación más clara, desde la recepción hasta la entrega.</h1><p>Demo conceptual para validar el flujo de página pública, captación, cotizaciones y órdenes de servicio.</p><div class="pdcrm-login-note">Contenido provisional · Datos de demostración</div></div></div><section class="pdcrm-login-card"><div class="pdcrm-login-brand"><span class="pdcrm-brand-mark">${crmIcon('car', 22)}</span><div><strong>Taller Demo</strong><small>Panel interno</small></div></div><span class="pdcrm-demo-label">ENTORNO DE DEMOSTRACIÓN</span><h2>Iniciar sesión</h2><p class="pdcrm-login-copy">Elige un acceso para mostrar la interfaz de cada rol.</p><form id="pdcrm-login-form"><label>Usuario<input name="username" autocomplete="username" placeholder="admin, recolector o ventas" required /></label><label>Clave<input name="password" type="password" autocomplete="current-password" placeholder="••••••••" required /></label><p class="pdcrm-login-error" id="pdcrm-login-error" role="alert"></p><button class="pdcrm-button pdcrm-button-primary pdcrm-button-full" type="submit">Entrar a la demo ${crmIcon('arrow', 16)}</button></form><div class="pdcrm-quick-logins"><span>Accesos rápidos</span><div><button type="button" data-login-quick="admin">Administrador <b>admin / admin</b></button><button type="button" data-login-quick="recolector">Recolector <b>recolector / recolector</b></button><button type="button" data-login-quick="ventas">Ventas <b>ventas / ventas</b></button></div></div><a class="pdcrm-login-public" href="/">← Volver a la página pública</a></section></main>`; }
function navLink(item, activeView) { return `<a class="pdcrm-nav-link ${activeView === item.view ? 'active' : ''}" href="${item.href}" data-route="${item.href}">${crmIcon(item.icon, 17)}<span>${item.label}</span></a>`; }
function crmShell(route) { const user = CRM_DEMO_USERS[crmSession.username]; const items = ROLE_NAV[crmSession.role]; return `<div class="pdcrm-app"><aside class="pdcrm-sidebar" id="pdcrm-sidebar"><div class="pdcrm-side-top"><a class="pdcrm-brand" href="/" aria-label="Volver a la página pública"><span class="pdcrm-brand-mark">${crmIcon('car', 20)}</span><span><strong>Taller Demo</strong><small>Panel interno</small></span></a><span class="pdcrm-demo-pill">DATOS DE DEMOSTRACIÓN</span></div><div class="pdcrm-role-card"><span class="pdcrm-avatar">${user.initials}</span><div><strong>${user.name}</strong><small>${user.label}</small></div></div><nav class="pdcrm-nav" aria-label="Navegación del sistema">${items.map((item) => navLink(item, route.view)).join('')}</nav><div class="pdcrm-side-bottom"><div class="pdcrm-side-note">${crmIcon('alert', 15)}<span>Demo conceptual<br /><b>Proceso real pendiente de validar</b></span></div><a class="pdcrm-public-link" href="/">${crmIcon('external', 15)} Ver página pública</a><button class="pdcrm-logout" type="button" data-action="logout">${crmIcon('back', 15)} Cerrar sesión</button></div></aside><button class="pdcrm-overlay" type="button" data-action="close-sidebar" aria-label="Cerrar menú"></button><main class="pdcrm-main"><header class="pdcrm-topbar"><button class="pdcrm-mobile-menu" type="button" data-action="toggle-sidebar" aria-label="Abrir menú">${crmIcon('menu', 21)}</button><div class="pdcrm-breadcrumbs" id="pdcrm-breadcrumbs"></div><div class="pdcrm-top-actions"><span class="pdcrm-environment">${crmIcon('check', 13)} Entorno demo</span><span class="pdcrm-top-avatar">${user.initials}</span></div></header><div class="pdcrm-content" id="pdcrm-content"></div></main><div class="pdcrm-toast" id="pdcrm-toast" role="status" aria-live="polite"></div><div id="pdcrm-modal-root"></div></div>`; }
function pageHeader(eyebrow, title, copy, action = '') { return `<div class="pdcrm-page-header"><div><span class="pdcrm-eyebrow">${eyebrow}</span><h1>${title}</h1><p>${copy}</p></div>${action}</div>`; }
function button(route, label, icon = 'arrow', kind = 'primary') { return `<a class="pdcrm-button pdcrm-button-${kind}" href="${route}" data-route="${route}">${label}${crmIcon(icon, 16)}</a>`; }
function metric(icon, label, value, detail, tone = 'mint') { return `<article class="pdcrm-metric pdcrm-tone-${tone}"><span class="pdcrm-metric-icon">${crmIcon(icon, 18)}</span><span class="pdcrm-metric-label">${label}</span><strong>${value}</strong><small>${detail}</small></article>`; }
function statusBadge(status) { return `<span class="pdcrm-status ${crmStatusClass(status)}"><i></i>${crmStatus(status)}</span>`; }
function panelHeader(kicker, title, action = '') { return `<div class="pdcrm-panel-header"><div><span class="pdcrm-panel-kicker">${kicker}</span><h2>${title}</h2></div>${action}</div>`; }
function emptyState(title, text, action = '') { return `<div class="pdcrm-empty">${crmIcon('search', 26)}<strong>${title}</strong><p>${text}</p>${action}</div>`; }
function dataCallout(title, text, tone = '') { return `<div class="pdcrm-callout ${tone}">${crmIcon('alert', 17)}<div><strong>${title}</strong><span>${text}</span></div><b>DEMO</b></div>`; }

function dashboardAdminView() { const pendingQuotes = crmState.quotes.filter((quote) => ['borrador', 'enviada'].includes(quote.status)).length; const activeOrders = crmState.orders.filter((order) => order.status !== 'cerrada').length; const receivable = crmState.receivables.filter((item) => item.status !== 'pagada').reduce((sum, item) => sum + item.amount, 0); const payable = crmState.payables.filter((item) => item.status !== 'pagada').reduce((sum, item) => sum + item.amount, 0); return `${pageHeader('PD-054 / Panel interno', 'Resumen general del taller', 'Control visual de la operación para priorizar vehículos, cotizaciones, cobros y seguimientos.', button('/crm/cotizaciones/nueva', 'Nueva cotización', 'plus'))}${dataCallout('Esta es una demostración conceptual.', 'Clientes, montos, responsables y estados son ficticios. El proceso real del taller queda pendiente de validar.')}<div class="pdcrm-metrics">${metric('car', 'Vehículos en proceso', activeOrders, 'Recepción a entrega', 'mint')}${metric('order', 'Órdenes activas', activeOrders, 'Sin cerrar', 'blue')}${metric('quote', 'Cotizaciones pendientes', pendingQuotes, 'Por revisar o enviar', 'purple')}${metric('wallet', 'Cuentas por cobrar', crmAmount(receivable), 'Montos demo pendientes', 'orange')}${metric('receipt', 'Cuentas por pagar', crmAmount(payable), 'Proveedores ficticios', 'rose')}${metric('clock', 'Seguimientos', crmState.followups.filter((item) => item.status !== 'Listo').length, 'Tareas por atender', 'slate')}</div><div class="pdcrm-grid-2"><section class="pdcrm-panel"><div class="pdcrm-panel-header"><div><span class="pdcrm-panel-kicker">Operación en taller</span><h2>Vehículos actualmente en proceso</h2></div>${button('/crm/ordenes', 'Ver órdenes', 'arrow', 'text')}</div><div class="pdcrm-order-cards">${crmState.orders.filter((order) => order.status !== 'cerrada').map((order) => { const client = crmClient(order.clientId); return `<a class="pdcrm-order-card" href="/crm/ordenes/${order.id}" data-route="/crm/ordenes/${order.id}"><div><strong>${order.id}</strong>${statusBadge(order.status)}</div><b>${client.vehicle} · ${client.year}</b><span>${client.name} · ${crmEsc(order.reportedIssue)}</span><small>Actualizado ${order.updated}</small></a>`; }).join('')}</div></section><section class="pdcrm-panel"><div class="pdcrm-panel-header"><div><span class="pdcrm-panel-kicker">Control</span><h2>Alertas y tareas pendientes</h2></div><span class="pdcrm-live">Actualizado ahora</span></div><div class="pdcrm-task-list"><div><span class="pdcrm-task-dot orange"></span><span><strong>COT-024 requiere seguimiento</strong><small>Cliente pendiente de confirmación · hoy</small></span>${crmIcon('arrow', 14)}</div><div><span class="pdcrm-task-dot blue"></span><span><strong>Asignar responsable a OS-018</strong><small>Diagnóstico en curso · pendiente</small></span>${crmIcon('arrow', 14)}</div><div><span class="pdcrm-task-dot rose"></span><span><strong>Revisar saldo CxC-009</strong><small>Regla de cobro por confirmar</small></span>${crmIcon('arrow', 14)}</div></div></section></div><div class="pdcrm-grid-2"><section class="pdcrm-panel"><div class="pdcrm-panel-header"><div><span class="pdcrm-panel-kicker">Actividad reciente</span><h2>Lo último en la demo</h2></div></div><div class="pdcrm-activity-list">${crmState.activity.slice(0, 5).map((item) => `<a href="${item.route}" data-route="${item.route}"><span>${crmIcon(item.icon, 16)}</span><span><strong>${crmEsc(item.title)}</strong><small>${crmEsc(item.detail)}</small></span>${crmIcon('arrow', 14)}</a>`).join('')}</div></section><section class="pdcrm-panel"><div class="pdcrm-panel-header"><div><span class="pdcrm-panel-kicker">Visibilidad financiera</span><h2>Resumen de cuentas</h2></div>${button('/crm/cobrar', 'Ver cuentas', 'arrow', 'text')}</div><div class="pdcrm-finance-lines"><div><span>Por cobrar</span><strong>${crmAmount(receivable)}</strong><small>${crmState.receivables.filter((item) => item.status !== 'pagada').length} registros pendientes</small></div><div><span>Por pagar</span><strong>${crmAmount(payable)}</strong><small>${crmState.payables.filter((item) => item.status !== 'pagada').length} registros pendientes</small></div><div><span>Seguimientos abiertos</span><strong>${crmState.followups.filter((item) => item.status !== 'Listo').length}</strong><small>Agenda visual de demostración</small></div></div></section></div>`; }
function dashboardSalesView() { const leads = crmLeads(); const newLeads = leads.filter((lead) => lead.status === 'nuevo').length; const chatLeads = leads.filter((lead) => lead.source === 'Chatbot web').length; const pending = leads.filter((lead) => ['nuevo', 'seguimiento'].includes(lead.status)).length; return `${pageHeader('Ventas / Captación', 'Resumen de oportunidades', 'Lee rápidamente los leads que llegan desde la página pública y prepara el siguiente contacto.', button('/crm/ventas/leads-chatbot', 'Ver leads del chatbot', 'arrow'))}${dataCallout('La captación está conectada a la demo.', 'Los leads del chatbot se guardan localmente en este navegador y aparecen aquí al recargar.', 'success')}<div class="pdcrm-metrics">${metric('user', 'Nuevos leads', newLeads, 'Requieren primer contacto', 'mint')}${metric('phone', 'Leads del chatbot', chatLeads, 'Fuente Chatbot web', 'blue')}${metric('quote', 'Cotizaciones en curso', crmState.quotes.filter((quote) => quote.status !== 'rechazada').length, 'Incluye propuestas demo', 'purple')}${metric('clock', 'Próximas acciones', pending, 'Seguimientos abiertos', 'orange')}</div><div class="pdcrm-grid-2"><section class="pdcrm-panel"><div class="pdcrm-panel-header"><div><span class="pdcrm-panel-kicker">Entrada reciente</span><h2>Leads que necesitan atención</h2></div>${button('/crm/ventas/leads-chatbot', 'Ver todos', 'arrow', 'text')}</div><div class="pdcrm-lead-preview">${leads.slice(0, 4).map((lead) => leadPreview(lead)).join('')}</div></section><section class="pdcrm-panel"><div class="pdcrm-panel-header"><div><span class="pdcrm-panel-kicker">Agenda comercial</span><h2>Próximas acciones</h2></div></div><div class="pdcrm-task-list">${crmState.followups.map((item) => `<div><span class="pdcrm-task-dot ${item.status === 'Listo' ? 'mint' : 'orange'}"></span><span><strong>${item.title}</strong><small>${item.contact} · ${item.due}</small></span><button class="pdcrm-icon-button" data-action="simulate-followup" data-id="${item.id}" title="Marcar como realizada">${crmIcon('check', 15)}</button></div>`).join('')}</div></section></div>`; }
function dashboardCollectorView() { const today = crmState.receptions[0]; return `${pageHeader('Recolector / Mi jornada', 'Recepciones de hoy', 'Una interfaz simplificada para registrar el ingreso del vehículo desde teléfono o tablet.', button('/crm/recolector/nueva-recepcion', 'Nueva recepción', 'plus'))}${dataCallout('Flujo guiado para el recolector.', 'Incluye inventario, daños preexistentes, fotografías, firma y PDF simulado.', 'success')}<div class="pdcrm-metrics pdcrm-collector-metrics">${metric('clock', 'Jornada', '08:00–17:00', 'Horario demo', 'mint')}${metric('car', 'Asignados', '03', 'Vehículos en ruta', 'blue')}${metric('camera', 'Evidencias', '12', 'Fotografías de demo', 'purple')}${metric('check', 'Completadas', '02', 'Recepciones hoy', 'orange')}</div><div class="pdcrm-mobile-actions"><a href="/crm/recolector/nueva-recepcion" data-route="/crm/recolector/nueva-recepcion" class="pdcrm-mobile-action primary">${crmIcon('plus', 24)}<strong>Nueva recepción</strong><small>Iniciar flujo paso a paso</small></a><a href="/crm/recolector/recepciones" data-route="/crm/recolector/recepciones" class="pdcrm-mobile-action">${crmIcon('file', 24)}<strong>Mis recepciones</strong><small>Consultar estados y PDF</small></a></div><div class="pdcrm-grid-2"><section class="pdcrm-panel"><div class="pdcrm-panel-header"><div><span class="pdcrm-panel-kicker">Última recepción</span><h2>Actividad reciente</h2></div>${statusBadge('diagnostico')}</div><div class="pdcrm-reception-highlight"><span class="pdcrm-big-icon">${crmIcon('car', 24)}</span><div><strong>${today.client}</strong><span>${today.vehicle}</span><small>${today.id} · ${today.date} · ${today.photos} evidencias</small></div>${today.signed ? '<span class="pdcrm-signed">Firma registrada</span>' : ''}</div></section><section class="pdcrm-panel"><div class="pdcrm-panel-header"><div><span class="pdcrm-panel-kicker">Vehículos asignados</span><h2>Mi ruta</h2></div></div><div class="pdcrm-route-list"><div><b>01</b><span><strong>Toyota Corolla · DEMO-001</strong><small>Zona 10 · Ventana 09:00</small></span>${statusBadge('nueva')}</div><div><b>02</b><span><strong>Honda CR-V · DEMO-002</strong><small>Zona 14 · Ventana 11:30</small></span>${statusBadge('contactado')}</div><div><b>03</b><span><strong>Nissan Versa · DEMO-004</strong><small>Zona 15 · Ventana 15:00</small></span>${statusBadge('pendiente')}</div></div></section></div>`; }
function leadPreview(lead) { return `<a class="pdcrm-lead-row" href="/crm/ventas/${lead.source === 'Chatbot web' ? 'leads-chatbot' : 'leads-web'}/${lead.id}" data-route="/crm/ventas/${lead.source === 'Chatbot web' ? 'leads-chatbot' : 'leads-web'}/${lead.id}"><span class="pdcrm-avatar small">${lead.name.split(' ').map((part) => part[0]).slice(0, 2).join('')}</span><span><strong>${crmEsc(lead.name)}</strong><small>${crmEsc(lead.vehicle)} · ${crmEsc(lead.service)}</small></span>${statusBadge(lead.status)}${crmIcon('arrow', 14)}</a>`; }

function leadsView(source = '') { const leads = crmLeads().filter((lead) => !source || lead.source === source); const title = source === 'Chatbot web' ? 'Leads del chatbot' : source === 'Página web' ? 'Leads de la página web' : 'Leads'; const copy = source === 'Chatbot web' ? 'Solicitudes que dejaron sus datos en el asistente conversacional de la página pública.' : 'Personas interesadas captadas desde la experiencia pública del taller.'; return `${pageHeader('Ventas / Captación', title, copy, button('/crm/ventas/leads-chatbot', 'Abrir chatbot demo', 'phone', 'secondary'))}<div class="pdcrm-toolbar"><label class="pdcrm-search">${crmIcon('search', 17)}<input type="search" placeholder="Buscar nombre, teléfono o vehículo…" data-lead-search /></label><span class="pdcrm-toolbar-meta">${leads.length} registros · Datos de demostración</span></div><div class="pdcrm-lead-grid" id="pdcrm-lead-grid">${leadCards(leads)}</div>`; }
function leadCards(leads) { if (!leads.length) return emptyState('Todavía no hay leads aquí', 'Cuando una persona complete el chatbot, aparecerá en esta bandeja.'); return leads.map((lead) => `<article class="pdcrm-lead-card" data-lead-card data-search-value="${crmEsc([lead.name, lead.phone, lead.vehicle, lead.service].join(' ')).toLowerCase()}"><div class="pdcrm-lead-card-top"><span class="pdcrm-avatar">${lead.name.split(' ').map((part) => part[0]).slice(0, 2).join('')}</span><div><strong>${crmEsc(lead.name)}</strong><small>${crmEsc(lead.phone)} · ${crmEsc(lead.date)}</small></div>${statusBadge(lead.status)}</div><div class="pdcrm-lead-details"><div><span>Vehículo</span><strong>${crmEsc(lead.vehicle)}</strong></div><div><span>Servicio</span><strong>${crmEsc(lead.service)}</strong></div><div><span>Fuente</span><strong>${crmEsc(lead.source)}</strong></div></div><p>“${crmEsc(lead.description)}”</p><div class="pdcrm-lead-actions"><a class="pdcrm-button pdcrm-button-secondary" href="/crm/ventas/${lead.source === 'Chatbot web' ? 'leads-chatbot' : 'leads-web'}/${lead.id}" data-route="/crm/ventas/${lead.source === 'Chatbot web' ? 'leads-chatbot' : 'leads-web'}/${lead.id}">Ver detalle</a><button class="pdcrm-button pdcrm-button-soft" type="button" data-action="contact-lead" data-id="${lead.id}">${crmIcon('phone', 14)} Contactar</button><button class="pdcrm-button pdcrm-button-soft" type="button" data-action="quote-from-lead" data-id="${lead.id}">${crmIcon('quote', 14)} Crear cotización</button><button class="pdcrm-button pdcrm-button-ghost" type="button" data-action="schedule-lead" data-id="${lead.id}">Programar seguimiento</button></div></article>`).join(''); }
function leadDetailView(lead) { if (!lead) return `${pageHeader('Ventas / Leads', 'Lead no encontrado', 'La ficha ya no está disponible en esta demo.', button('/crm/ventas/leads-chatbot', 'Volver a leads', 'back', 'secondary'))}${emptyState('Sin datos', 'Regresa a la bandeja de leads.')}`; const message = `Hola ${lead.name}, gracias por escribirnos. Vimos tu consulta sobre ${lead.vehicle} y ${lead.service.toLowerCase()}. Podemos coordinar una revisión de demostración. ¿Qué horario te funciona?`; return `${pageHeader(`Ventas / ${lead.source}`, lead.name, 'Detalle del lead y próximas acciones comerciales. Todos los datos son ficticios.', `<a class="pdcrm-back-link" href="/crm/ventas/${lead.source === 'Chatbot web' ? 'leads-chatbot' : 'leads-web'}" data-route="/crm/ventas/${lead.source === 'Chatbot web' ? 'leads-chatbot' : 'leads-web'}">${crmIcon('back', 15)} Volver a leads</a>`)}<div class="pdcrm-detail-grid"><section class="pdcrm-panel"><div class="pdcrm-panel-header"><div><span class="pdcrm-panel-kicker">Ficha de contacto</span><h2>Información recibida</h2></div>${statusBadge(lead.status)}</div><div class="pdcrm-facts"><div><span>Nombre</span><strong>${crmEsc(lead.name)}</strong></div><div><span>Teléfono</span><strong>${crmEsc(lead.phone)}</strong></div><div><span>Correo</span><strong>${crmEsc(lead.email)}</strong></div><div><span>Vehículo</span><strong>${crmEsc(lead.vehicle)}</strong></div><div><span>Servicio de interés</span><strong>${crmEsc(lead.service)}</strong></div><div><span>Fuente</span><strong>${crmEsc(lead.source)}</strong></div></div><div class="pdcrm-detail-message"><span>Mensaje</span><p>${crmEsc(lead.description)}</p></div><div class="pdcrm-detail-note"><span>Notas</span><p>${crmEsc(lead.notes || 'Sin notas registradas.')}</p></div></section><aside class="pdcrm-detail-side"><section class="pdcrm-panel">${panelHeader('Siguiente acción', 'Trabajar este lead')}<div class="pdcrm-action-stack"><button class="pdcrm-button pdcrm-button-primary" type="button" data-action="contact-lead" data-id="${lead.id}">${crmIcon('phone', 16)} Preparar contacto</button><button class="pdcrm-button pdcrm-button-secondary" type="button" data-action="quote-from-lead" data-id="${lead.id}">${crmIcon('quote', 16)} Preparar cotización</button><button class="pdcrm-button pdcrm-button-soft" type="button" data-action="schedule-lead" data-id="${lead.id}">${crmIcon('clock', 16)} Programar seguimiento</button></div><div class="pdcrm-sim-note">${crmIcon('alert', 14)} No se envían mensajes automáticamente. La acción es simulada.</div></section><section class="pdcrm-panel">${panelHeader('Borrador', 'Mensaje sugerido')}<p class="pdcrm-message-preview">${crmEsc(message)}</p><button class="pdcrm-button pdcrm-button-ghost pdcrm-button-full" type="button" data-action="copy-message" data-message="${crmEsc(message)}">${crmIcon('check', 15)} Copiar mensaje</button></section></aside></div>`; }

function clientsView(sales = false) { return `${pageHeader(sales ? 'Ventas / Relación' : 'Operación / Registro', sales ? 'Clientes' : 'Clientes y vehículos', 'Registros ficticios para mostrar la relación entre cada persona y su vehículo.', button('/crm/cotizaciones/nueva', 'Nueva cotización', 'plus'))}<div class="pdcrm-toolbar"><label class="pdcrm-search">${crmIcon('search', 17)}<input type="search" placeholder="Buscar cliente, vehículo o placa…" data-client-search /></label><span class="pdcrm-toolbar-meta">${crmState.clients.length} registros demo</span></div><section class="pdcrm-panel pdcrm-table-panel" id="pdcrm-clients-panel">${clientRows('')}</section>`; }
function clientRows(query) { const normalized = (query || '').toLowerCase(); const rows = crmState.clients.filter((client) => [client.name, client.vehicle, client.plate, client.phone].join(' ').toLowerCase().includes(normalized)); if (!rows.length) return emptyState('No hay coincidencias', 'Prueba con otro nombre, vehículo o placa demo.'); return `<div class="pdcrm-table-wrap"><table class="pdcrm-table"><thead><tr><th>Cliente</th><th>Vehículo</th><th>Contacto</th><th>Actividad</th><th></th></tr></thead><tbody>${rows.map((client) => `<tr><td><div class="pdcrm-person"><span class="pdcrm-avatar">${client.name.split(' ').map((word) => word[0]).slice(0, 2).join('')}</span><span><strong>${crmEsc(client.name)}</strong><small>${client.id} · Demo</small></span></div></td><td><strong>${crmEsc(client.vehicle)}</strong><small>${client.year} · Placa ${client.plate}</small></td><td><strong>${crmEsc(client.phone)}</strong><small>${crmEsc(client.email)}</small></td><td>${statusBadge('contactado')}</td><td><button class="pdcrm-icon-button" type="button" data-action="client-options" data-id="${client.id}">${crmIcon('more', 17)}</button></td></tr>`).join('')}</tbody></table></div>`; }

function quotesView(sales = false) { return `${pageHeader(sales ? 'Ventas / Propuestas' : 'Operación / Seguimiento', 'Cotizaciones', 'Prepara, presenta y convierte propuestas visuales antes de generar una orden de servicio.', button('/crm/cotizaciones/nueva', 'Nueva cotización', 'plus'))}<div class="pdcrm-toolbar"><div class="pdcrm-filter-tabs"><button class="active" type="button" data-action="filter-quotes" data-filter="all">Todas <b>${crmState.quotes.length}</b></button><button type="button" data-action="filter-quotes" data-filter="borrador">Borradores</button><button type="button" data-action="filter-quotes" data-filter="enviada">Enviadas</button><button type="button" data-action="filter-quotes" data-filter="aprobada">Aprobadas</button></div><span class="pdcrm-toolbar-meta">Montos ficticios · sin facturación</span></div><section class="pdcrm-panel pdcrm-table-panel" id="pdcrm-quotes-panel">${quoteRows('all')}</section>`; }
function quoteRows(filter) { const quotes = crmState.quotes.filter((quote) => filter === 'all' || quote.status === filter); if (!quotes.length) return emptyState('No hay cotizaciones aquí', 'Crea una propuesta para continuar el recorrido.', button('/crm/cotizaciones/nueva', 'Crear cotización', 'plus', 'secondary')); return `<div class="pdcrm-table-wrap"><table class="pdcrm-table"><thead><tr><th>Cotización</th><th>Cliente / vehículo</th><th>Fecha</th><th>Estado</th><th>Total demo</th><th></th></tr></thead><tbody>${quotes.map((quote) => { const client = crmClient(quote.clientId); return `<tr class="pdcrm-click-row"><td><a href="/crm/cotizaciones/${quote.id}" data-route="/crm/cotizaciones/${quote.id}"><strong>${quote.id}</strong><small>${quote.items.length} concepto${quote.items.length === 1 ? '' : 's'}</small></a></td><td><strong>${crmEsc(client.name)}</strong><small>${crmEsc(client.vehicle)} · ${client.year}</small></td><td><strong>${quote.date}</strong><small>Válida hasta ${quote.validUntil}</small></td><td>${statusBadge(quote.status)}</td><td><strong>${crmAmount(quoteTotals(quote).total)}</strong><small>monto demo</small></td><td><button class="pdcrm-icon-button" type="button" data-route="/crm/cotizaciones/${quote.id}" aria-label="Abrir ${quote.id}">${crmIcon('arrow', 17)}</button></td></tr>`; }).join('')}</tbody></table></div>`; }

function quoteEditorView(id, isSales = false) { if (!crmQuoteDraft || crmQuoteDraftKey !== id) { const existing = id === 'new' ? null : crmQuote(id); crmQuoteDraft = existing ? cloneDemo(existing) : { id: null, clientId: '', vehicleId: '', status: 'borrador', date: crmDate(), validUntil: 'Por confirmar', notes: '', discount: 0, taxRate: 0, items: [{ type: 'Servicio', description: '', quantity: 1, price: 0 }] }; crmQuoteDraftKey = id; } const draft = crmQuoteDraft; const selectedClient = crmClient(draft.clientId); const totals = quoteTotals(draft); const quoteBase = isSales ? '/crm/ventas/cotizaciones' : '/crm/cotizaciones'; return `${pageHeader(id === 'new' ? 'Cotizaciones / Nueva' : `Cotizaciones / ${draft.id}`, id === 'new' ? 'Nueva cotización' : `Editar ${draft.id}`, 'Los campos son editables para mostrar una propuesta visual. Precios y reglas reales quedan pendientes de confirmar.', `<a class="pdcrm-back-link" href="${quoteBase}" data-route="${quoteBase}">${crmIcon('back', 15)} Volver a cotizaciones</a>`)}<form id="pdcrm-quote-form" class="pdcrm-quote-layout" novalidate><div class="pdcrm-quote-main"><section class="pdcrm-panel">${panelHeader('Paso 1', 'Cliente y vehículo', '<span class="pdcrm-step-count">01 / 03</span>')}<div class="pdcrm-form-grid"><label>Cliente<select name="clientId" data-quote-field="clientId" required><option value="">Seleccionar cliente</option>${crmState.clients.map((client) => `<option value="${client.id}" ${client.id === draft.clientId ? 'selected' : ''}>${crmEsc(client.name)} · ${client.id}</option>`).join('')}</select></label><label>Vehículo<select name="vehicleId" data-quote-field="vehicleId" required><option value="">${draft.clientId ? 'Seleccionar vehículo' : 'Selecciona primero un cliente'}</option>${crmState.clients.filter((client) => client.id === draft.clientId).map((client) => `<option value="${client.id}" ${client.id === draft.vehicleId ? 'selected' : ''}>${crmEsc(client.vehicle)} · ${client.year} · ${client.plate}</option>`).join('')}</select></label></div><div class="pdcrm-selected-client"><span class="pdcrm-avatar">${selectedClient.name.split(' ').map((word) => word[0]).slice(0, 2).join('')}</span><div><strong>${crmEsc(selectedClient.name)}</strong><small>${crmEsc(selectedClient.vehicle)} · ${selectedClient.year} · Placa ${selectedClient.plate}</small></div><span class="pdcrm-mini-badge">Demo</span></div></section><section class="pdcrm-panel">${panelHeader('Paso 2', 'Servicios y repuestos', '<button class="pdcrm-text-button" type="button" data-action="add-quote-line">＋ Agregar concepto</button>')}<div class="pdcrm-lines-head"><span>Tipo</span><span>Descripción</span><span>Cantidad</span><span>Precio demo</span><span></span></div><div class="pdcrm-lines">${draft.items.map((item, index) => `<div class="pdcrm-line-item"><select data-quote-line="type" data-index="${index}"><option ${item.type === 'Servicio' ? 'selected' : ''}>Servicio</option><option ${item.type === 'Repuesto' ? 'selected' : ''}>Repuesto</option></select><input data-quote-line="description" data-index="${index}" value="${crmEsc(item.description)}" placeholder="Ej. Diagnóstico general" /><input data-quote-line="quantity" data-index="${index}" type="number" min="1" value="${item.quantity}" aria-label="Cantidad" /><input data-quote-line="price" data-index="${index}" type="number" min="0" value="${item.price}" aria-label="Precio demo" /><button class="pdcrm-icon-button" type="button" data-action="remove-quote-line" data-index="${index}" aria-label="Eliminar concepto">${crmIcon('close', 15)}</button></div>`).join('')}</div><p class="pdcrm-helper">Los precios son demostrativos y no representan una cotización final.</p></section><section class="pdcrm-panel">${panelHeader('Paso 3', 'Condiciones y notas', '<span class="pdcrm-step-count">03 / 03</span>')}<div class="pdcrm-form-grid"><label>Descuento demo<input type="number" min="0" name="discount" data-quote-field="discount" value="${draft.discount}" /></label><label>Impuesto configurable<input type="number" min="0" name="taxRate" data-quote-field="taxRate" value="${draft.taxRate}" /></label></div><label class="pdcrm-full-field">Notas<textarea name="notes" data-quote-field="notes" rows="4" placeholder="Notas para la propuesta…">${crmEsc(draft.notes)}</textarea></label></section><div class="pdcrm-quote-actions"><button class="pdcrm-button pdcrm-button-secondary" type="submit" value="save">Guardar borrador</button><button class="pdcrm-button pdcrm-button-primary" type="submit" value="send">Guardar y marcar enviada ${crmIcon('arrow', 16)}</button></div></div><aside class="pdcrm-quote-side"><section class="pdcrm-preview-card"><div class="pdcrm-preview-top"><span>Vista previa</span><span>DEMO</span></div><div class="pdcrm-preview-brand"><span class="pdcrm-brand-mark">${crmIcon('car', 18)}</span><div><strong>Taller Demo</strong><small>Propuesta de servicio automotriz</small></div></div><div class="pdcrm-preview-meta"><span>${draft.id || 'COT-NUEVA'}</span><span>${draft.date}</span></div><div class="pdcrm-preview-client"><small>Preparada para</small><strong>${crmEsc(selectedClient.name)}</strong><span>${crmEsc(selectedClient.vehicle)} · ${selectedClient.year}</span></div><div class="pdcrm-preview-items">${draft.items.filter((item) => item.description).map((item) => `<div><span>${crmEsc(item.description)} × ${item.quantity}</span><strong>${crmAmount((Number(item.price) || 0) * (Number(item.quantity) || 0))}</strong></div>`).join('') || '<small class="pdcrm-muted">Agrega conceptos para actualizar la vista previa.</small>'}</div><div class="pdcrm-totals"><div><span>Subtotal</span><strong data-summary="subtotal">${crmAmount(totals.subtotal)}</strong></div><div><span>Descuento</span><strong data-summary="discount">− ${crmAmount(totals.discount)}</strong></div><div><span>Impuesto</span><strong data-summary="tax">${crmAmount(totals.tax)}</strong></div><div class="total"><span>Total demo</span><strong data-summary="total">${crmAmount(totals.total)}</strong></div></div><small class="pdcrm-preview-disclaimer">Documento visual. No es factura ni compromiso de precio.</small></section><div class="pdcrm-save-card">${crmIcon('file', 17)}<strong>Documento asociado</strong><small>Al guardar podrás mostrar una vista de PDF simulado y relacionar la cotización con una orden.</small></div></aside></form>`; }

function quoteDetailView(quote, isSales = false) { if (!quote) return `${pageHeader('Cotizaciones', 'Cotización no encontrada', 'La propuesta no está disponible en esta demo.', button(isSales ? '/crm/ventas/cotizaciones' : '/crm/cotizaciones', 'Volver a cotizaciones', 'back', 'secondary'))}${emptyState('Sin datos', 'Regresa al listado para continuar.')}`; const client = crmClient(quote.clientId); const total = quoteTotals(quote).total; const base = isSales ? '/crm/ventas/cotizaciones' : '/crm/cotizaciones'; return `${pageHeader(`Cotizaciones / ${quote.id}`, quote.id, 'Vista de la propuesta, aprobación simulada y relación con la orden de servicio.', `<a class="pdcrm-back-link" href="${base}" data-route="${base}">${crmIcon('back', 15)} Volver</a>`)}<div class="pdcrm-detail-actions"><span>${statusBadge(quote.status)}</span><a class="pdcrm-button pdcrm-button-secondary" href="${base}/${quote.id}/edit" data-route="${base}/${quote.id}/edit">Editar propuesta</a>${quote.status === 'aprobada' ? `<button class="pdcrm-button pdcrm-button-primary" type="button" data-action="convert-quote" data-id="${quote.id}">${crmIcon('order', 16)} Convertir en orden</button>` : `<button class="pdcrm-button pdcrm-button-soft" type="button" data-action="quote-status" data-id="${quote.id}" data-status="aprobada">${crmIcon('check', 16)} Aprobar simulación</button>`}</div><div class="pdcrm-detail-grid"><section class="pdcrm-panel pdcrm-document"><div class="pdcrm-document-head"><div><span class="pdcrm-panel-kicker">Taller Demo</span><h2>Propuesta de servicio</h2><small>Contenido provisional · documento visual</small></div><div><span>${quote.id}</span><strong>${quote.date}</strong><small>Válida hasta ${quote.validUntil}</small></div></div><div class="pdcrm-document-banner">${statusBadge(quote.status)}<span>DATOS DE DEMOSTRACIÓN</span></div><div class="pdcrm-facts"><div><span>Cliente</span><strong>${crmEsc(client.name)}</strong><small>${crmEsc(client.phone)}</small></div><div><span>Vehículo</span><strong>${crmEsc(client.vehicle)}</strong><small>${client.year} · ${client.plate}</small></div><div><span>Fuente</span><strong>${quote.orderId ? `Orden ${quote.orderId}` : 'Pendiente de convertir'}</strong><small>Relación demo</small></div></div><table class="pdcrm-document-table"><thead><tr><th>Tipo</th><th>Descripción</th><th>Cant.</th><th>Precio</th><th>Total</th></tr></thead><tbody>${quote.items.map((item) => `<tr><td>${item.type}</td><td><strong>${crmEsc(item.description)}</strong></td><td>${item.quantity}</td><td>${crmAmount(item.price)}</td><td><strong>${crmAmount(item.price * item.quantity)}</strong></td></tr>`).join('')}</tbody></table><div class="pdcrm-document-bottom"><div><span>Notas</span><p>${crmEsc(quote.notes || 'Sin notas adicionales.')}</p></div><div class="pdcrm-totals"><div><span>Subtotal</span><strong>${crmAmount(quoteTotals(quote).subtotal)}</strong></div><div><span>Descuento</span><strong>− ${crmAmount(quoteTotals(quote).discount)}</strong></div><div class="total"><span>Total demo</span><strong>${crmAmount(total)}</strong></div></div></div><div class="pdcrm-document-foot">Este documento es una simulación para validar el alcance. No es factura ni cotización comercial definitiva.</div></section><aside class="pdcrm-detail-side"><section class="pdcrm-panel">${panelHeader('Estado de la propuesta', 'Acciones de demostración')}<div class="pdcrm-action-stack"><button class="pdcrm-button pdcrm-button-soft" type="button" data-action="quote-status" data-id="${quote.id}" data-status="enviada">Marcar enviada</button><button class="pdcrm-button pdcrm-button-soft" type="button" data-action="quote-status" data-id="${quote.id}" data-status="rechazada">Marcar rechazada</button><button class="pdcrm-button pdcrm-button-ghost" type="button" data-action="simulate-pdf" data-id="${quote.id}">${crmIcon('download', 15)} Descargar PDF simulado</button></div><div class="pdcrm-sim-note">${crmIcon('alert', 14)} Envío, firma y aprobación son visuales.</div></section><section class="pdcrm-panel">${panelHeader('Próximo paso', 'Relación con orden')}<div class="pdcrm-related-box">${quote.orderId ? `<strong>${quote.orderId}</strong><span>Orden creada desde esta cotización.</span><a href="/crm/ordenes/${quote.orderId}" data-route="/crm/ordenes/${quote.orderId}">Abrir orden ${crmIcon('arrow', 14)}</a>` : '<strong>Sin orden relacionada</strong><span>Aprueba la propuesta y conviértela en una orden de servicio demo.</span>'}</div></section></aside></div>`; }

function ordersView() { const active = crmState.orders.filter((order) => order.status !== 'cerrada').length; const responsibleOptions = [...new Set(crmState.orders.map((order) => order.responsible))]; return `${pageHeader('Operación / Taller', 'Órdenes de servicio', 'Sigue el avance desde recepción hasta entrega con indicadores, filtros y detalle de cada vehículo.', button('/crm/ordenes/nueva', 'Nueva orden', 'plus'))}<div class="pdcrm-order-metrics">${metric('order', 'Órdenes activas', active, 'Sin cerrar', 'mint')}${metric('clock', 'En diagnóstico', crmState.orders.filter((order) => order.status === 'diagnostico').length, 'Por evaluar', 'blue')}${metric('wrench', 'En reparación', crmState.orders.filter((order) => order.status === 'reparacion').length, 'Trabajo en curso', 'orange')}${metric('check', 'Listas para entregar', crmState.orders.filter((order) => order.status === 'lista').length, 'Siguiente paso: entrega', 'purple')}</div><section class="pdcrm-panel pdcrm-order-toolbar"><div class="pdcrm-order-filters"><label class="pdcrm-search">${crmIcon('search', 17)}<input type="search" placeholder="Buscar orden, cliente, vehículo…" data-order-search /></label><select data-order-filter="status"><option value="all">Todos los estados</option>${['nueva', 'diagnostico', 'cotizacion_pendiente', 'aprobada_orden', 'reparacion', 'lista', 'cerrada'].map((status) => `<option value="${status}">${crmStatus(status)}</option>`).join('')}</select><select data-order-filter="responsible"><option value="all">Todos los responsables</option>${responsibleOptions.map((item) => `<option>${crmEsc(item)}</option>`).join('')}</select><input type="date" data-order-filter="date" aria-label="Filtrar por fecha" /></div><span class="pdcrm-toolbar-meta">Filtros visuales · fechas demo</span></section><section class="pdcrm-panel pdcrm-table-panel" id="pdcrm-orders-panel">${orderRows()}</section>`; }
function orderRows() { const f = crmOrderFilters; const orders = crmState.orders.filter((order) => { const haystack = [order.id, crmClient(order.clientId).name, crmClient(order.clientId).vehicle, order.reportedIssue].join(' ').toLowerCase(); return (!f.query || haystack.includes(f.query.toLowerCase())) && (f.status === 'all' || order.status === f.status) && (f.responsible === 'all' || order.responsible === f.responsible) && (!f.date || order.dateReceived === f.date); }); if (!orders.length) return emptyState('No hay órdenes con estos filtros', 'Prueba cambiando el estado, responsable o fecha.'); return `<div class="pdcrm-table-wrap"><table class="pdcrm-table pdcrm-order-table"><thead><tr><th>Orden</th><th>Cliente / vehículo</th><th>Problema reportado</th><th>Recepción</th><th>Responsable</th><th>Estimado</th><th>Estado</th><th>Actualización</th><th></th></tr></thead><tbody>${orders.map((order) => { const client = crmClient(order.clientId); const next = CRM_ORDER_STEPS[CRM_ORDER_STEPS.indexOf(order.status) + 1]; return `<tr><td><a href="/crm/ordenes/${order.id}" data-route="/crm/ordenes/${order.id}"><strong>${order.id}</strong><small>${order.quoteId ? `Desde ${order.quoteId}` : 'Orden demo'}</small></a></td><td><strong>${crmEsc(client.name)}</strong><small>${crmEsc(client.vehicle)} · ${client.year}</small></td><td><strong>${crmEsc(order.reportedIssue)}</strong><small>Placa ${client.plate}</small></td><td>${order.dateReceived}</td><td>${crmEsc(order.responsible)}</td><td><strong>${crmAmount(order.estimate)}</strong><small>monto demo</small></td><td>${statusBadge(order.status)}</td><td>${order.updated}</td><td>${next ? `<button class="pdcrm-small-action" type="button" data-action="advance-order" data-id="${order.id}">Avanzar ${crmStatus(next)} ${crmIcon('arrow', 13)}</button>` : '<span class="pdcrm-muted">Flujo cerrado</span>'}</td></tr>`; }).join('')}</tbody></table></div>`; }
function orderDetailView(order) { if (!order) return `${pageHeader('Órdenes', 'Orden no encontrada', 'Regresa al listado para continuar.', button('/crm/ordenes', 'Ver órdenes', 'arrow', 'secondary'))}${emptyState('Sin datos', 'La orden no existe en esta demo.')}`; const client = crmClient(order.clientId); const index = CRM_ORDER_STEPS.indexOf(order.status); const next = CRM_ORDER_STEPS[index + 1]; return `${pageHeader(`Órdenes / ${order.id}`, order.id, 'Detalle operativo para mostrar progreso, problema reportado, documentos y próximos pasos.', `<a class="pdcrm-back-link" href="/crm/ordenes" data-route="/crm/ordenes">${crmIcon('back', 15)} Volver a órdenes</a>`)}<div class="pdcrm-detail-actions"><span>${statusBadge(order.status)}</span>${next ? `<button class="pdcrm-button pdcrm-button-primary" type="button" data-action="advance-order" data-id="${order.id}">Avanzar a ${crmStatus(next)} ${crmIcon('arrow', 16)}</button>` : '<span class="pdcrm-complete-chip">Orden cerrada</span>'}</div><div class="pdcrm-order-detail"><section class="pdcrm-panel"><div class="pdcrm-panel-header"><div><span class="pdcrm-panel-kicker">Progreso visual</span><h2>Del ingreso a la entrega</h2></div><span class="pdcrm-mini-badge">Demo</span></div><div class="pdcrm-progress">${CRM_ORDER_STEPS.map((step, stepIndex) => `<div class="${stepIndex <= index ? 'current' : ''}"><span>${stepIndex + 1}</span><small>${crmStatus(step)}</small></div>`).join('')}</div><div class="pdcrm-facts"><div><span>Cliente</span><strong>${crmEsc(client.name)}</strong><small>${crmEsc(client.phone)}</small></div><div><span>Vehículo</span><strong>${crmEsc(client.vehicle)}</strong><small>${client.year} · ${client.plate}</small></div><div><span>Recepción</span><strong>${order.dateReceived}</strong><small>Última actualización: ${order.updated}</small></div><div><span>Responsable</span><strong>${crmEsc(order.responsible)}</strong><small>Pendiente de confirmar</small></div><div><span>Monto estimado</span><strong>${crmAmount(order.estimate)}</strong><small>Importe demo</small></div><div><span>Cotización</span><strong>${order.quoteId || 'Sin relación'}</strong><small>${order.quoteId ? 'Origen visible' : 'Por confirmar'}</small></div></div></section><div class="pdcrm-grid-2"><section class="pdcrm-panel">${panelHeader('Ingreso', 'Problema reportado')}<p class="pdcrm-large-note">${crmEsc(order.reportedIssue)}</p><div class="pdcrm-notes-box"><span>Notas internas</span><p>${crmEsc(order.notes)}</p></div></section><section class="pdcrm-panel">${panelHeader('Documentos y evidencia', 'Asociados')}<div class="pdcrm-doc-list"><div>${crmIcon('file', 17)}<span><strong>Recepción ${order.id}</strong><small>PDF simulado · disponible</small></span><button class="pdcrm-icon-button" data-action="simulate-pdf" data-id="${order.id}">${crmIcon('download', 15)}</button></div><div>${crmIcon('camera', 17)}<span><strong>Fotografías de ingreso</strong><small>4 evidencias · demo</small></span><span class="pdcrm-muted">Ver</span></div><div>${crmIcon('quote', 17)}<span><strong>${order.quoteId || 'Cotización pendiente'}</strong><small>Relación visual</small></span>${order.quoteId ? `<a href="/crm/cotizaciones/${order.quoteId}" data-route="/crm/cotizaciones/${order.quoteId}">${crmIcon('arrow', 15)}</a>` : ''}</div></div></section></div><section class="pdcrm-panel">${panelHeader('Historial de cambios', 'Actividad de la orden')}<div class="pdcrm-timeline"><div><span>09 sep</span><strong>Recepción registrada</strong><small>Datos y evidencias demo confirmados</small></div><div class="active"><span>Ahora</span><strong>${crmStatus(order.status)}</strong><small>Estado actual de la orden</small></div><div><span>Siguiente</span><strong>${next ? crmStatus(next) : 'Entrega cerrada'}</strong><small>Acción visual pendiente</small></div></div></section></div>`; }

function receptionOverviewView() { return `${pageHeader('Operación / Recepción', 'Recepción de vehículos', 'Consulta el ingreso, evidencias y documentos generados por el flujo de recepción.', button('/crm/recolector/nueva-recepcion', 'Abrir flujo de recepción', 'plus'))}${dataCallout('La recepción es un flujo mobile-first.', 'Incluye inventario, daños preexistentes, fotografías, firma y PDF simulado.', 'success')}<section class="pdcrm-panel pdcrm-table-panel">${panelHeader('Registros recientes', 'Recepciones demo')}<div class="pdcrm-table-wrap"><table class="pdcrm-table"><thead><tr><th>Recepción</th><th>Cliente</th><th>Vehículo</th><th>Fecha</th><th>Evidencias</th><th>Firma</th><th>Estado</th></tr></thead><tbody>${crmState.receptions.map((item) => `<tr><td><strong>${item.id}</strong><small>Datos de demostración</small></td><td>${crmEsc(item.client)}</td><td>${crmEsc(item.vehicle)}</td><td>${item.date}</td><td>${item.photos} fotografías</td><td>${item.signed ? '<span class="pdcrm-signed">Registrada</span>' : 'Pendiente'}</td><td>${statusBadge(item.status === 'PDF generado' ? 'pagada' : 'diagnostico')}</td></tr>`).join('')}</tbody></table></div></section>`; }
function receptionDefault() { return { step: 0, completed: false, clientName: '', phone: '', vehicle: '', year: '', plate: '', source: '', conditions: '', inventory: ['Llaves', 'Gato', 'Repuesto', 'Documentos'], inventoryChecked: [], damages: '', photos: [], observations: '', signature: false }; }
function receptionWizardView() { if (!crmReceptionDraft) crmReceptionDraft = loadJson('pd-054-reception-draft-v1', receptionDefault()); if (crmReceptionDraft.completed) return `${pageHeader('Recolector / Recepción', 'Recepción confirmada', 'La demostración guardó una recepción local con sus evidencias y documentos visuales.', button('/crm/recolector/nueva-recepcion', 'Nueva recepción', 'plus'))}<div class="pdcrm-confirm-card"><span class="pdcrm-confirm-icon">✓</span><h2>Recepción lista para presentar</h2><p>Se registró un PDF simulado, una firma demo y ${crmReceptionDraft.photos.length || 0} fotografías locales.</p><div class="pdcrm-confirm-actions"><button class="pdcrm-button pdcrm-button-primary" type="button" data-action="simulate-pdf">Generar PDF simulado ${crmIcon('download', 16)}</button><button class="pdcrm-button pdcrm-button-secondary" type="button" data-action="new-reception">Iniciar otra recepción</button></div><span class="pdcrm-sim-note">Acción simulada para la demo · No se envía ningún documento real.</span></div>`; const step = crmReceptionDraft.step; return `${pageHeader(`Recolector / Paso ${step + 1} de ${CRM_RECEPTION_STEPS.length}`, CRM_RECEPTION_STEPS[step], 'Completa cada paso para mostrar una recepción clara desde el teléfono o tablet.', `<a class="pdcrm-back-link" href="/crm/recolector" data-route="/crm/recolector">${crmIcon('back', 15)} Volver a jornada</a>`)}<div class="pdcrm-stepper">${CRM_RECEPTION_STEPS.map((label, index) => `<div class="${index === step ? 'active' : ''} ${index < step ? 'done' : ''}"><span>${index < step ? '✓' : String(index + 1).padStart(2, '0')}</span><small>${label}</small></div>`).join('')}</div><form id="pdcrm-reception-form" class="pdcrm-panel pdcrm-reception-form">${receptionStepMarkup(step)}<div class="pdcrm-reception-actions">${step > 0 ? '<button class="pdcrm-button pdcrm-button-secondary" type="submit" name="reception-action" value="prev">← Anterior</button>' : '<span></span>'}${step < CRM_RECEPTION_STEPS.length - 1 ? '<button class="pdcrm-button pdcrm-button-primary" type="submit" name="reception-action" value="next">Continuar →</button>' : '<button class="pdcrm-button pdcrm-button-primary" type="submit" name="reception-action" value="complete">Confirmar y generar PDF simulado →</button>'}</div></form>`; }
function receptionStepMarkup(step) { const d = crmReceptionDraft; if (step === 0) return `<div class="pdcrm-form-grid"><label>Nombre del cliente<input data-reception-field="clientName" value="${crmEsc(d.clientName)}" placeholder="Ej. Ana Castillo" required /></label><label>Teléfono<input data-reception-field="phone" value="${crmEsc(d.phone)}" placeholder="5550 0000" required /></label></div><p class="pdcrm-helper">Paso 1 de 10 · Datos de demostración, no se guardan en un sistema productivo.</p>`; if (step === 1) return `<div class="pdcrm-form-grid"><label>Marca y modelo<input data-reception-field="vehicle" value="${crmEsc(d.vehicle)}" placeholder="Ej. Mazda 3" required /></label><label>Año<input data-reception-field="year" value="${crmEsc(d.year)}" placeholder="2017" /></label><label>Placa<input data-reception-field="plate" value="${crmEsc(d.plate)}" placeholder="DEMO-000" /></label></div>`; if (step === 2) return `<div class="pdcrm-choice-grid"><label class="pdcrm-choice"><input type="radio" name="reception-source" data-reception-field="source" value="Recolectado en domicilio" ${d.source === 'Recolectado en domicilio' ? 'checked' : ''} /><span><strong>Recolectado</strong><small>Recepción coordinada en ubicación del cliente.</small></span></label><label class="pdcrm-choice"><input type="radio" name="reception-source" data-reception-field="source" value="Recibido en taller" ${d.source === 'Recibido en taller' ? 'checked' : ''} /><span><strong>Recibido en taller</strong><small>El cliente llevó el vehículo.</small></span></label><label class="pdcrm-choice"><input type="radio" name="reception-source" data-reception-field="source" value="Otro origen" ${d.source === 'Otro origen' ? 'checked' : ''} /><span><strong>Otro origen</strong><small>Dato pendiente de validar.</small></span></label></div>`; if (step === 3) return `<label class="pdcrm-full-field">Condiciones de recepción<select data-reception-field="conditions"><option value="">Seleccionar condición</option><option ${d.conditions === 'Normal' ? 'selected' : ''}>Normal</option><option ${d.conditions === 'Con observaciones' ? 'selected' : ''}>Con observaciones</option><option ${d.conditions === 'Pendiente de confirmar' ? 'selected' : ''}>Pendiente de confirmar</option></select></label><p class="pdcrm-helper">Registra el estado visible al recibirlo. Las reglas reales quedan pendientes de confirmar.</p>`; if (step === 4) return `<div class="pdcrm-inventory-grid">${d.inventory.map((item) => `<label><input type="checkbox" data-inventory="${crmEsc(item)}" ${d.inventoryChecked.includes(item) ? 'checked' : ''} /> <span>${item}</span></label>`).join('')}</div><p class="pdcrm-helper">Marca lo que queda registrado en el vehículo.</p>`; if (step === 5) return `<label class="pdcrm-full-field">Daños preexistentes<textarea data-reception-field="damages" rows="5" placeholder="Ej. Rayón en puerta trasera derecha…">${crmEsc(d.damages)}</textarea></label><div class="pdcrm-evidence-note">${crmIcon('alert', 15)} Registra daños visibles antes de avanzar.</div>`; if (step === 6) return `<div class="pdcrm-upload-box"><input id="reception-photos" type="file" accept="image/*" multiple data-reception-files /><label for="reception-photos">${crmIcon('camera', 24)}<strong>Cargar fotografías</strong><small>Selecciona archivos para mostrar miniaturas en la demo.</small></label></div><div class="pdcrm-photo-grid">${d.photos.map((photo, index) => `<div class="pdcrm-photo-thumb"><span>${index + 1}</span><small>${crmEsc(photo)}</small></div>`).join('') || '<span class="pdcrm-muted">Aún no hay fotografías cargadas.</span>'}</div>`; if (step === 7) return `<label class="pdcrm-full-field">Observaciones<textarea data-reception-field="observations" rows="5" placeholder="Notas para el cliente o el taller…">${crmEsc(d.observations)}</textarea></label>`; if (step === 8) return `<div class="pdcrm-signature-box ${d.signature ? 'signed' : ''}"><div class="pdcrm-signature-line">${d.signature ? 'Firma demo registrada' : 'Área de firma del cliente'}</div><button class="pdcrm-button pdcrm-button-secondary" type="button" data-action="register-signature">${d.signature ? 'Rehacer firma' : 'Registrar firma demo'}</button></div><p class="pdcrm-helper">La firma es visual y no tiene validez legal.</p>`; return `<div class="pdcrm-final-check"><span class="pdcrm-confirm-icon">✓</span><h2>Todo listo para confirmar</h2><p>Se generará un PDF simulado con los datos, daños, inventario, fotografías y firma demo.</p><div class="pdcrm-summary-list"><span><b>Cliente</b>${crmEsc(d.clientName || 'Por confirmar')}</span><span><b>Vehículo</b>${crmEsc(d.vehicle || 'Por confirmar')} ${crmEsc(d.year)}</span><span><b>Evidencias</b>${d.photos.length} fotografías · ${d.signature ? 'Firma registrada' : 'Firma pendiente'}</span></div></div>`; }

function genericModuleView(view) { const modules = { services: ['Servicios y mantenimientos', 'Catálogo visual de servicios, mantenimiento y conceptos que podrían convertirse en cotización.', 'El catálogo real, precios y periodicidades quedan pendientes de confirmar.'], followups: ['Seguimientos', 'Agenda de tareas y contactos que necesitan una próxima acción.', 'La automatización de recordatorios todavía no está conectada.'], documents: ['Documentos y PDFs', 'Repositorio visual de propuestas, recepciones y archivos asociados.', 'Los PDFs se simulan en el navegador y no se envían de forma automática.'], users: ['Usuarios y permisos', 'Vista conceptual de personas, roles y accesos del panel.', 'La autenticación y los permisos reales no están implementados.'], settings: ['Configuración', 'Datos editables del taller, catálogos y preferencias de la demo.', 'Nombre comercial, logo y datos operativos están pendientes de confirmar.'], 'sales-followups': ['Seguimientos comerciales', 'Organiza próximos contactos y estados de oportunidad.', 'No se envían mensajes ni recordatorios reales.'], opportunities: ['Oportunidades', 'Vista de oportunidades por etapa para conversar sobre el proceso comercial.', 'Las etapas y probabilidades son ficticias.'], communications: ['Comunicaciones', 'Mensajes preparados para WhatsApp, llamada o correo.', 'Solo se preparan borradores; no existe integración productiva.'], 'assigned-vehicles': ['Vehículos asignados', 'Ruta y vehículos que el recolector debe atender durante la jornada.', 'Ubicaciones y horarios son datos de demostración.'], evidence: ['Evidencias', 'Fotografías y observaciones asociadas a recepciones demo.', 'Los archivos quedan solo en la sesión local del navegador.'], history: ['Historial', 'Recepciones anteriores y documentos generados visualmente.', 'Contenido provisional para validar el recorrido.'], 'collector-receptions': ['Mis recepciones', 'Consulta el estado de cada recepción registrada desde el móvil.', 'Las recepciones son ficticias y se guardan localmente.'], 'sales-clients': ['Clientes', 'Relación de contactos que llegaron por las oportunidades de ventas.', 'La ficha real se definirá al validar el proceso.'] }; const [title, copy, note] = modules[view] || ['Módulo en preparación', 'Esta pantalla forma parte del mapa visual del sistema interno.', 'Función visual de demostración.']; if (view === 'services') return `${pageHeader('Administrador / Catálogo', title, copy, '<button class="pdcrm-button pdcrm-button-primary" type="button" data-action="simulate-save">Agregar servicio</button>')}<div class="pdcrm-service-grid">${APP_CONFIG.services.slice(0, 6).map(([name, description, icon], index) => `<article class="pdcrm-service-card"><span>${icons[icon] || icons.wrench}</span><small>0${index + 1}</small><h3>${name}</h3><p>${description}</p><button type="button" data-action="simulate-save">Editar concepto</button></article>`).join('')}</div>`; if (view === 'users') return `${pageHeader('Administrador / Control', title, copy, '<button class="pdcrm-button pdcrm-button-primary" type="button" data-action="simulate-save">Invitar usuario</button>')}<section class="pdcrm-panel pdcrm-table-panel">${panelHeader('Accesos demo', 'Usuarios y roles')}<div class="pdcrm-table-wrap"><table class="pdcrm-table"><thead><tr><th>Usuario</th><th>Rol</th><th>Acceso</th><th>Estado</th></tr></thead><tbody>${Object.entries(CRM_DEMO_USERS).map(([username, user]) => `<tr><td><div class="pdcrm-person"><span class="pdcrm-avatar">${user.initials}</span><span><strong>${user.name}</strong><small>${username} · clave demo</small></span></div></td><td>${user.label}</td><td>Interfaz ${user.label.toLowerCase()}</td><td>${statusBadge('contactado')}</td></tr>`).join('')}</tbody></table></div></section>`; if (view === 'documents') return `${pageHeader('Administrador / Archivo', title, copy, '<button class="pdcrm-button pdcrm-button-primary" type="button" data-action="simulate-pdf">Generar PDF demo</button>')}<div class="pdcrm-document-grid"><article><span>${crmIcon('quote', 24)}</span><strong>COT-024 · Propuesta de servicio</strong><small>PDF simulado · ${crmDate()}</small><button type="button" data-action="simulate-pdf">Ver documento</button></article><article><span>${crmIcon('file', 24)}</span><strong>REC-014 · Recepción de vehículo</strong><small>Firma y fotografías · demo</small><button type="button" data-action="simulate-pdf">Ver documento</button></article><article><span>${crmIcon('order', 24)}</span><strong>OS-018 · Orden de servicio</strong><small>Documentos asociados</small><button type="button" data-action="simulate-pdf">Ver documento</button></article></div>`; return `${pageHeader('Módulo visual', title, copy, '<button class="pdcrm-button pdcrm-button-primary" type="button" data-action="simulate-save">Nueva acción demo</button>')}${dataCallout('Función visual de demostración.', note, 'warning')}<div class="pdcrm-placeholder-grid"><section class="pdcrm-panel"><div class="pdcrm-placeholder-graphic">${crmIcon(view === 'assigned-vehicles' ? 'car' : view === 'communications' ? 'phone' : 'clock', 31)}</div><h2>Todo listo para conversar</h2><p>Esta pantalla tiene estructura, estados y acciones para validar el alcance con el cliente antes de construir la operación real.</p><button class="pdcrm-button pdcrm-button-secondary" type="button" data-action="simulate-save">Probar acción simulada</button></section><section class="pdcrm-panel"><div class="pdcrm-mini-list"><div><span>01</span><strong>Datos ficticios</strong><small>Marcados como demo en todo el recorrido.</small></div><div><span>02</span><strong>Estado local</strong><small>Las acciones se conservan en este navegador.</small></div><div><span>03</span><strong>Siguiente paso</strong><small>Validar proceso, usuarios y prioridades.</small></div></div></section></div>`; }
function financeView(type) { const payable = type === 'payables'; const items = payable ? crmState.payables : crmState.receivables; const pending = items.filter((item) => item.status !== 'pagada').reduce((sum, item) => sum + item.amount, 0); return `${pageHeader(payable ? 'Control / Gastos' : 'Control / Cobros', payable ? 'Cuentas por pagar' : 'Cuentas por cobrar', payable ? 'Visualiza obligaciones ficticias con proveedores sin asumir reglas contables del taller.' : 'Relaciona saldos demo con órdenes o cotizaciones aprobadas sin simular facturación ni pagos reales.', `<span class="pdcrm-header-stat">${crmAmount(pending)} pendientes</span>`)}${dataCallout(payable ? 'Reglas contables pendientes de confirmar.' : 'Proceso pendiente de validar.', payable ? 'Este módulo solo muestra una estructura visual para conversar sobre el proceso real.' : 'Vencimientos, comprobantes y pagos son únicamente estados de demostración.', 'warning')}<section class="pdcrm-panel pdcrm-table-panel"><div class="pdcrm-table-wrap"><table class="pdcrm-table"><thead><tr><th>Referencia</th><th>${payable ? 'Proveedor' : 'Cliente'}</th><th>Concepto</th><th>Vencimiento</th><th>Estado</th><th>Monto demo</th></tr></thead><tbody>${items.map((item) => { const client = payable ? null : crmClient(item.clientId); return `<tr><td><strong>${item.id}</strong><small>${item.orderId || 'Registro demo'}</small></td><td><strong>${payable ? item.supplier : client.name}</strong><small>${payable ? 'Proveedor ficticio' : client.vehicle}</small></td><td><strong>${item.concept}</strong><small>Sin ${payable ? 'contabilización' : 'factura fiscal'} real</small></td><td>${item.due}</td><td>${statusBadge(item.status)}</td><td><strong>${crmAmount(item.amount)}</strong></td></tr>`; }).join('')}</tbody></table></div></section>`; }
function breadcrumbs(route) { const labels = { 'admin-dashboard': ['Administrador', 'Resumen'], 'sales-dashboard': ['Ventas', 'Resumen'], 'collector-dashboard': ['Recolector', 'Inicio'], receptions: ['Administrador', 'Recepción de vehículos'], clients: ['Administrador', 'Clientes y vehículos'], quotes: ['Administrador', 'Cotizaciones'], 'sales-quotes': ['Ventas', 'Cotizaciones'], orders: ['Administrador', 'Órdenes de servicio'], 'order-detail': ['Órdenes de servicio', route.id], 'quote-detail': ['Cotizaciones', route.id], 'quote-new': ['Cotizaciones', 'Nueva'], 'quote-edit': ['Cotizaciones', route.id], 'lead-detail': ['Ventas', 'Detalle del lead'], 'leads-web': ['Ventas', 'Leads de la página web'], 'leads-chatbot': ['Ventas', 'Leads del chatbot'], 'new-reception': ['Recolector', 'Nueva recepción'] }; const current = labels[route.view] || [crmSession.label, 'Módulo']; return `<span>Panel interno</span>${current.map((label) => `${crmIcon('arrow', 11)}<strong>${label}</strong>`).join('')}`; }
function bindCrmElements() { const selectors = ['[data-route]', '[data-action]', '[data-login-quick]']; document.querySelectorAll(selectors.join(',')).forEach((element) => { if (!element.dataset.pdcrmBound) { element.dataset.pdcrmBound = '1'; element.addEventListener('click', (event) => { if (element.dataset.route) { event.preventDefault(); navigateCrm(element.dataset.route); return; } if (element.dataset.action === 'logout') { saveSession(null); crmSession = null; renderCrm(); return; } if (element.dataset.action === 'advance-order') { advanceOrder(element.dataset.id); return; } handleCrmClick({ target: element, preventDefault: () => event.preventDefault() }); }); } }); document.querySelectorAll('[data-quote-field],[data-quote-line],[data-order-filter],[data-reception-field],[data-inventory],[data-reception-files],[data-lead-search],[data-client-search],[data-order-search]').forEach((element) => { if (!element.dataset.pdcrmBound) { element.dataset.pdcrmBound = '1'; const liveInput = element.matches('[data-lead-search],[data-client-search],[data-order-search],[data-quote-line],[data-reception-field]'); element.addEventListener(liveInput ? 'input' : 'change', liveInput ? (event) => handleCrmInput({ target: element }) : (event) => handleCrmChange({ target: element })); if (element.matches('[data-reception-field]')) element.addEventListener('change', () => handleCrmChange({ target: element })); } }); document.querySelectorAll('#pdcrm-login-form,#pdcrm-quote-form,#pdcrm-order-form,#pdcrm-reception-form').forEach((form) => { if (!form.dataset.pdcrmBound) { form.dataset.pdcrmBound = '1'; form.addEventListener('submit', (event) => handleCrmSubmit({ target: form, preventDefault: () => event.preventDefault(), submitter: event.submitter })); } }); }
function renderCrm() { if (!crmSession) { document.body.innerHTML = loginView(); document.title = 'Acceso demo · Taller Demo'; bindCrmElements(); return; } let route = routeView(window.location.pathname); if (route.view === 'home') { const target = defaultRouteForRole(crmSession.role); window.history.replaceState({}, '', target); route = routeView(target); } if (!canAccessRoute(route)) route = { view: 'access-denied' }; if (!document.querySelector('.pdcrm-app')) document.body.innerHTML = crmShell(route); const content = document.querySelector('#pdcrm-content'); if (!content) return; document.querySelector('#pdcrm-breadcrumbs').innerHTML = breadcrumbs(route); const views = { 'admin-dashboard': dashboardAdminView, 'sales-dashboard': dashboardSalesView, 'collector-dashboard': dashboardCollectorView, receptions: receptionOverviewView, clients: () => clientsView(false), quotes: () => quotesView(false), 'sales-quotes': () => quotesView(true), orders: ordersView, 'quote-new': () => quoteEditorView('new', crmSession.role === 'ventas'), 'quote-edit': () => quoteEditorView(route.id, crmSession.role === 'ventas'), 'quote-detail': () => quoteDetailView(crmQuote(route.id), crmSession.role === 'ventas'), 'order-detail': () => orderDetailView(crmOrder(route.id)), 'order-new': orderEditorView, 'lead-detail': () => leadDetailView(crmLeads().find((lead) => lead.id === route.id)), 'leads-web': () => leadsView('Página web'), 'leads-chatbot': () => leadsView('Chatbot web'), 'sales-clients': () => clientsView(true), receivables: () => financeView('receivables'), payables: () => financeView('payables'), 'new-reception': receptionWizardView, 'collector-receptions': () => genericModuleView('collector-receptions'), 'assigned-vehicles': () => genericModuleView('assigned-vehicles'), evidence: () => genericModuleView('evidence'), history: () => genericModuleView('history'), services: () => genericModuleView('services'), followups: () => genericModuleView('followups'), documents: () => genericModuleView('documents'), users: () => genericModuleView('users'), settings: () => genericModuleView('settings'), 'sales-followups': () => genericModuleView('sales-followups'), opportunities: () => genericModuleView('opportunities'), communications: () => genericModuleView('communications') }; content.innerHTML = (views[route.view] || accessDeniedView)(); document.body.classList.remove('pdcrm-menu-open'); document.querySelector('#pdcrm-sidebar')?.classList.remove('open'); bindCrmElements(); }
function accessDeniedView() { return `${pageHeader('Acceso restringido', 'Este módulo no pertenece a tu rol', 'La demo cambia la interfaz y el menú según el rol seleccionado.', button(defaultRouteForRole(crmSession.role), 'Volver a mi panel', 'back', 'secondary'))}${dataCallout('Módulo no disponible en este acceso.', 'Inicia sesión con Administrador, Recolector o Ventas para mostrar otra experiencia.', 'warning')}`; }
function orderEditorView() { return `${pageHeader('Órdenes / Nueva', 'Nueva orden de servicio', 'Formulario visual para registrar una orden manualmente.', '<a class="pdcrm-back-link" href="/crm/ordenes" data-route="/crm/ordenes">← Volver a órdenes</a>')}<form class="pdcrm-panel pdcrm-simple-form" id="pdcrm-order-form"><div class="pdcrm-form-grid"><label>Cliente<select name="clientId" required><option value="">Seleccionar cliente</option>${crmState.clients.map((client) => `<option value="${client.id}">${crmEsc(client.name)} · ${client.vehicle}</option>`).join('')}</select></label><label>Responsable<select name="responsible"><option>Por asignar</option><option>Recolector Demo</option><option>Taller Demo</option></select></label><label>Problema reportado<input name="reportedIssue" required placeholder="Ej. Ruido al frenar" /></label><label>Fecha de recepción<input name="dateReceived" type="date" value="2026-09-16" /></label><label>Monto estimado<input name="estimate" type="number" min="0" value="0" /></label><label>Notas<textarea name="notes" rows="3">Orden creada para la demostración.</textarea></label></div><div class="pdcrm-quote-actions"><button class="pdcrm-button pdcrm-button-secondary" type="button" data-route="/crm/ordenes">Cancelar</button><button class="pdcrm-button pdcrm-button-primary" type="submit">Guardar orden demo ${crmIcon('arrow', 16)}</button></div></form>`; }
function navigateCrm(path, replace = false) { if (replace) window.history.replaceState({}, '', path); else window.history.pushState({}, '', path); renderCrm(); window.scrollTo({ top: 0, behavior: 'smooth' }); }
function showCrmToast(message, tone = 'success') { const toast = document.querySelector('#pdcrm-toast'); if (!toast) return; toast.className = `pdcrm-toast visible ${tone}`; toast.innerHTML = `${crmIcon(tone === 'error' ? 'alert' : 'check', 16)}<span>${crmEsc(message)}</span>`; clearTimeout(crmToastTimer); crmToastTimer = setTimeout(() => toast.classList.remove('visible'), 3600); }
function updateQuoteSummary() { if (!crmQuoteDraft) return; const total = quoteTotals(crmQuoteDraft); const values = { subtotal: crmAmount(total.subtotal), discount: `− ${crmAmount(total.discount)}`, tax: crmAmount(total.tax), total: crmAmount(total.total) }; Object.entries(values).forEach(([key, value]) => document.querySelectorAll(`[data-summary="${key}"]`).forEach((node) => { node.textContent = value; })); }
function saveQuoteFromForm(form, action) { const data = new FormData(form); crmQuoteDraft.clientId = data.get('clientId'); crmQuoteDraft.vehicleId = data.get('vehicleId'); crmQuoteDraft.discount = Number(data.get('discount')) || 0; crmQuoteDraft.taxRate = Number(data.get('taxRate')) || 0; crmQuoteDraft.notes = data.get('notes') || ''; if (!crmQuoteDraft.clientId || !crmQuoteDraft.vehicleId) return showCrmToast('Selecciona un cliente y un vehículo.', 'error'); if (!crmQuoteDraft.items.length || crmQuoteDraft.items.some((item) => !String(item.description).trim() || Number(item.quantity) < 1)) return showCrmToast('Completa la descripción y cantidad de cada concepto.', 'error'); if (!crmQuoteDraft.id) crmQuoteDraft.id = `COT-${String(crmState.quotes.length + 25).padStart(3, '0')}`; crmQuoteDraft.status = action === 'send' ? 'enviada' : 'borrador'; crmQuoteDraft.total = quoteTotals(crmQuoteDraft).total; const existing = crmState.quotes.findIndex((quote) => quote.id === crmQuoteDraft.id); if (existing >= 0) crmState.quotes[existing] = cloneDemo(crmQuoteDraft); else crmState.quotes.unshift(cloneDemo(crmQuoteDraft)); addActivity(action === 'send' ? 'quote' : 'check', `${crmQuoteDraft.id} ${action === 'send' ? 'marcada como enviada' : 'guardada como borrador'}`, `${crmClient(crmQuoteDraft.clientId).name} · ahora`, `/crm/cotizaciones/${crmQuoteDraft.id}`); saveCrmState(); const id = crmQuoteDraft.id; crmQuoteDraftKey = ''; navigateCrm(`/crm/cotizaciones/${id}`); showCrmToast(action === 'send' ? 'Cotización guardada y marcada como enviada.' : 'Cotización guardada como borrador.'); }
function updateQuoteStatus(id, status) { const quote = crmQuote(id); if (!quote) return; quote.status = status; addActivity(status === 'aprobada' ? 'check' : 'quote', `${quote.id} marcada como ${crmStatus(status).toLowerCase()}`, `${crmClient(quote.clientId).name} · ahora`, `/crm/cotizaciones/${quote.id}`); saveCrmState(); renderCrm(); showCrmToast(`La cotización quedó como ${crmStatus(status).toLowerCase()}.`); }
function convertQuoteToOrder(id) { const quote = crmQuote(id); if (!quote || quote.status !== 'aprobada') return showCrmToast('Aprueba la cotización antes de convertirla.', 'error'); if (quote.orderId) return navigateCrm(`/crm/ordenes/${quote.orderId}`); const orderId = `OS-${String(crmState.orders.length + 19).padStart(3, '0')}`; const order = { id: orderId, quoteId: quote.id, clientId: quote.clientId, vehicleId: quote.vehicleId, status: 'nueva', reportedIssue: 'Pendiente de confirmar con el cliente.', dateReceived: crmDate(), responsible: 'Por asignar', estimate: quoteTotals(quote).total, updated: 'Ahora', notes: 'Orden creada desde una cotización aprobada. Responsable, diagnóstico y notas reales pendientes de confirmar.', items: cloneDemo(quote.items) }; crmState.orders.unshift(order); quote.orderId = orderId; crmState.receivables.unshift({ id: `CxC-${String(crmState.receivables.length + 10).padStart(3, '0')}`, orderId, clientId: quote.clientId, concept: `Saldo de ${quote.id} · demo`, amount: quoteTotals(quote).total, status: 'pendiente', due: 'Por confirmar' }); addActivity('order', `${orderId} creada desde ${quote.id}`, `${crmClient(quote.clientId).name} · ahora`, `/crm/ordenes/${orderId}`); saveCrmState(); navigateCrm(`/crm/ordenes/${orderId}`); showCrmToast('Orden creada y saldo demo agregado a cuentas por cobrar.'); }
function advanceOrder(id) { const order = crmOrder(id); if (!order) return; const index = CRM_ORDER_STEPS.indexOf(order.status); if (index < CRM_ORDER_STEPS.length - 1) { order.status = CRM_ORDER_STEPS[index + 1]; order.updated = 'Ahora'; addActivity('order', `${order.id} pasó a ${crmStatus(order.status).toLowerCase()}`, `${crmClient(order.clientId).name} · ahora`, `/crm/ordenes/${order.id}`); saveCrmState(); renderCrm(); showCrmToast(`${order.id} ahora está ${crmStatus(order.status).toLowerCase()}.`); } }
function createQuoteFromLead(id) { const lead = crmLeads().find((item) => item.id === id); if (!lead) return; let client = crmState.clients.find((item) => item.phone === lead.phone); if (!client) { const vehicleMatch = String(lead.vehicle).match(/(.*?)(?:\s+)(\d{4})$/); client = { id: `CLI-${String(crmState.clients.length + 1).padStart(3, '0')}`, name: lead.name, phone: lead.phone, email: lead.email, vehicle: vehicleMatch ? vehicleMatch[1] : lead.vehicle, year: vehicleMatch ? vehicleMatch[2] : 'Por confirmar', plate: 'PEND-DEMO' }; crmState.clients.unshift(client); } const quoteId = `COT-${String(crmState.quotes.length + 25).padStart(3, '0')}`; crmState.quotes.unshift({ id: quoteId, clientId: client.id, vehicleId: client.id, status: 'borrador', date: crmDate(), validUntil: 'Por confirmar', notes: `Preparada desde ${lead.id}. ${lead.description}`, discount: 0, taxRate: 0, items: [{ type: 'Servicio', description: lead.service, quantity: 1, price: 0 }], leadId: lead.id }); addActivity('quote', `${quoteId} preparada desde ${lead.id}`, `${lead.name} · ahora`, `/crm/cotizaciones/${quoteId}`); saveCrmState(); navigateCrm(`/crm/${crmSession.role === 'ventas' ? 'ventas/cotizaciones' : 'cotizaciones'}/${quoteId}/edit`); showCrmToast('Cotización visual creada desde el lead.'); }
function updateLead(id, updates) { const leads = crmLeads(); const index = leads.findIndex((lead) => lead.id === id); if (index < 0) return; leads[index] = { ...leads[index], ...updates }; saveLeads(leads); }
function openContactModal(lead) { if (!lead) return; const message = `Hola ${lead.name}, gracias por escribirnos. Vimos tu consulta sobre ${lead.vehicle} y ${lead.service.toLowerCase()}. Podemos coordinar una revisión de demostración. ¿Qué horario te funciona?`; document.querySelector('#pdcrm-modal-root').innerHTML = `<div class="pdcrm-modal-backdrop" data-action="close-modal"><section class="pdcrm-modal" role="dialog" aria-modal="true" aria-labelledby="contact-modal-title"><button class="pdcrm-modal-close" type="button" data-action="close-modal">×</button><span class="pdcrm-eyebrow">Contacto simulado</span><h2 id="contact-modal-title">Preparar mensaje para ${crmEsc(lead.name)}</h2><p>El mensaje queda listo para copiar. No se envía automáticamente.</p><textarea id="pdcrm-contact-message" rows="6">${crmEsc(message)}</textarea><div class="pdcrm-modal-actions"><button class="pdcrm-button pdcrm-button-secondary" type="button" data-action="copy-contact">${crmIcon('check', 15)} Copiar mensaje</button><button class="pdcrm-button pdcrm-button-primary" type="button" data-action="mark-contacted" data-id="${lead.id}">Marcar como contactado</button></div><small class="pdcrm-modal-note">Acción simulada para la demo · Fuente: ${crmEsc(lead.source)}</small></section></div>`; bindCrmElements(); }
function completeReception() { const d = crmReceptionDraft; const reception = { id: `REC-${String(crmState.receptions.length + 15).padStart(3, '0')}`, client: d.clientName || 'Cliente demo', vehicle: `${d.vehicle || 'Vehículo demo'} ${d.year || ''}`.trim(), status: 'PDF generado', date: crmDate(), photos: d.photos.length, signed: d.signature }; crmState.receptions.unshift(reception); addActivity('car', `${reception.id} completada`, `${reception.client} · ${crmTime()}`, '/crm/recolector/recepciones'); d.completed = true; saveJson('pd-054-reception-draft-v1', d); saveCrmState(); renderCrm(); showCrmToast('Recepción guardada y PDF simulado generado.'); }

function handleCrmClick(event) { const routeTarget = event.target.closest('[data-route]'); if (routeTarget) { event.preventDefault(); navigateCrm(routeTarget.dataset.route || routeTarget.getAttribute('href')); return; } const quick = event.target.closest('[data-login-quick]'); if (quick) { const user = CRM_DEMO_USERS[quick.dataset.loginQuick]; document.querySelector('#pdcrm-login-form [name="username"]').value = quick.dataset.loginQuick; document.querySelector('#pdcrm-login-form [name="password"]').value = user.password; document.querySelector('#pdcrm-login-form').requestSubmit(); return; } const target = event.target.closest('[data-action]'); if (!target) return; const action = target.dataset.action; if (action === 'toggle-sidebar') { document.querySelector('#pdcrm-sidebar')?.classList.toggle('open'); document.body.classList.toggle('pdcrm-menu-open'); } if (action === 'close-sidebar') { document.querySelector('#pdcrm-sidebar')?.classList.remove('open'); document.body.classList.remove('pdcrm-menu-open'); } if (action === 'logout') { saveSession(null); crmSession = null; document.body.innerHTML = loginView(); } if (action === 'reset-demo' && window.confirm('¿Reiniciar todos los datos de demostración?')) { crmState = cloneDemo(CRM_DEFAULT_STATE); saveCrmState(); saveLeads(CRM_LEADS_DEFAULT); crmReceptionDraft = receptionDefault(); saveJson('pd-054-reception-draft-v1', crmReceptionDraft); navigateCrm(defaultRouteForRole(crmSession.role)); showCrmToast('Datos de demostración reiniciados.'); } if (action === 'add-quote-line') { crmQuoteDraft.items.push({ type: 'Servicio', description: '', quantity: 1, price: 0 }); renderCrm(); } if (action === 'remove-quote-line') { crmQuoteDraft.items.splice(Number(target.dataset.index), 1); if (!crmQuoteDraft.items.length) crmQuoteDraft.items.push({ type: 'Servicio', description: '', quantity: 1, price: 0 }); renderCrm(); } if (action === 'quote-status') updateQuoteStatus(target.dataset.id, target.dataset.status); if (action === 'convert-quote') convertQuoteToOrder(target.dataset.id); if (action === 'advance-order') advanceOrder(target.dataset.id); if (action === 'filter-quotes') { document.querySelectorAll('[data-action="filter-quotes"]').forEach((button) => button.classList.toggle('active', button === target)); const panel = document.querySelector('#pdcrm-quotes-panel'); if (panel) panel.innerHTML = quoteRows(target.dataset.filter); } if (action === 'contact-lead') openContactModal(crmLeads().find((lead) => lead.id === target.dataset.id)); if (action === 'quote-from-lead') createQuoteFromLead(target.dataset.id); if (action === 'schedule-lead') { updateLead(target.dataset.id, { status: 'seguimiento' }); showCrmToast('Seguimiento demo programado.'); renderCrm(); } if (action === 'simulate-followup') { const item = crmState.followups.find((entry) => entry.id === target.dataset.id); if (item) item.status = 'Listo'; saveCrmState(); renderCrm(); showCrmToast('Seguimiento marcado como realizado.'); } if (action === 'copy-message' || action === 'copy-contact') { const text = action === 'copy-contact' ? document.querySelector('#pdcrm-contact-message')?.value : target.dataset.message; navigator.clipboard?.writeText(text || '').then(() => showCrmToast('Mensaje copiado para la demo.')).catch(() => showCrmToast('Mensaje listo para copiar manualmente.')); } if (action === 'mark-contacted') { updateLead(target.dataset.id, { status: 'contactado' }); document.querySelector('#pdcrm-modal-root').innerHTML = ''; renderCrm(); showCrmToast('Lead marcado como contactado.'); } if (action === 'close-modal' && (event.target.classList.contains('pdcrm-modal-backdrop') || event.target.closest('.pdcrm-modal-close'))) document.querySelector('#pdcrm-modal-root').innerHTML = ''; if (action === 'simulate-pdf') showCrmToast('PDF simulado generado para la demo.'); if (action === 'simulate-save') showCrmToast('Acción simulada guardada localmente.'); if (action === 'new-reception') { crmReceptionDraft = receptionDefault(); saveJson('pd-054-reception-draft-v1', crmReceptionDraft); navigateCrm('/crm/recolector/nueva-recepcion'); } if (action === 'reception-next') { if (!validateReceptionStep()) return; crmReceptionDraft.step = Math.min(CRM_RECEPTION_STEPS.length - 1, crmReceptionDraft.step + 1); saveJson('pd-054-reception-draft-v1', crmReceptionDraft); renderCrm(); } if (action === 'reception-prev') { crmReceptionDraft.step = Math.max(0, crmReceptionDraft.step - 1); saveJson('pd-054-reception-draft-v1', crmReceptionDraft); renderCrm(); } if (action === 'register-signature') { crmReceptionDraft.signature = true; saveJson('pd-054-reception-draft-v1', crmReceptionDraft); renderCrm(); showCrmToast('Firma demo registrada.'); } if (action === 'complete-reception') { if (!validateReceptionStep()) return; completeReception(); } }
function validateReceptionStep() { const d = crmReceptionDraft; if (d.step === 0 && (!d.clientName || !d.phone)) { showCrmToast('Completa nombre y teléfono del cliente.', 'error'); return false; } if (d.step === 1 && !d.vehicle) { showCrmToast('Agrega al menos marca y modelo.', 'error'); return false; } if (d.step === 8 && !d.signature) { showCrmToast('Registra la firma demo antes de confirmar.', 'error'); return false; } return true; }
function handleCrmChange(event) { const target = event.target; if (target.matches('[data-quote-field]')) { crmQuoteDraft[target.dataset.quoteField] = ['discount', 'taxRate'].includes(target.dataset.quoteField) ? Number(target.value) || 0 : target.value; if (target.dataset.quoteField === 'clientId') { crmQuoteDraft.vehicleId = ''; renderCrm(); } else updateQuoteSummary(); } if (target.matches('[data-quote-line]')) { const item = crmQuoteDraft.items[Number(target.dataset.index)]; if (item) item[target.dataset.quoteLine] = ['quantity', 'price'].includes(target.dataset.quoteLine) ? Number(target.value) || 0 : target.value; updateQuoteSummary(); } if (target.matches('[data-order-filter]')) { crmOrderFilters[target.dataset.orderFilter] = target.value || 'all'; const panel = document.querySelector('#pdcrm-orders-panel'); if (panel) panel.innerHTML = orderRows(); } if (target.matches('[data-reception-field]')) { crmReceptionDraft[target.dataset.receptionField] = target.value; saveJson('pd-054-reception-draft-v1', crmReceptionDraft); } if (target.matches('[data-inventory]')) { crmReceptionDraft.inventoryChecked = [...document.querySelectorAll('[data-inventory]:checked')].map((input) => input.dataset.inventory); saveJson('pd-054-reception-draft-v1', crmReceptionDraft); } if (target.matches('[data-reception-files]')) { crmReceptionDraft.photos = [...target.files].map((file) => file.name); saveJson('pd-054-reception-draft-v1', crmReceptionDraft); renderCrm(); } }
function handleCrmInput(event) { const target = event.target; if (target.matches('[data-lead-search]')) { const query = target.value.toLowerCase(); document.querySelectorAll('[data-lead-card]').forEach((card) => { card.hidden = !card.dataset.searchValue.includes(query); }); } if (target.matches('[data-client-search]')) { const panel = document.querySelector('#pdcrm-clients-panel'); if (panel) panel.innerHTML = clientRows(target.value); } if (target.matches('[data-order-search]')) { crmOrderFilters.query = target.value; const panel = document.querySelector('#pdcrm-orders-panel'); if (panel) panel.innerHTML = orderRows(); } if (target.matches('[data-quote-line]')) { const item = crmQuoteDraft.items[Number(target.dataset.index)]; if (item) item[target.dataset.quoteLine] = ['quantity', 'price'].includes(target.dataset.quoteLine) ? Number(target.value) || 0 : target.value; updateQuoteSummary(); } if (target.matches('[data-reception-field]')) { crmReceptionDraft[target.dataset.receptionField] = target.value; saveJson('pd-054-reception-draft-v1', crmReceptionDraft); } }
function handleReceptionFormAction(action) { if (action === 'prev') { crmReceptionDraft.step = Math.max(0, crmReceptionDraft.step - 1); saveJson('pd-054-reception-draft-v1', crmReceptionDraft); renderCrm(); return; } if (action === 'complete') { if (validateReceptionStep()) completeReception(); return; } if (!validateReceptionStep()) return; crmReceptionDraft.step = Math.min(CRM_RECEPTION_STEPS.length - 1, crmReceptionDraft.step + 1); saveJson('pd-054-reception-draft-v1', crmReceptionDraft); renderCrm(); }
function handleCrmSubmit(event) { if (event.target.id === 'pdcrm-login-form') { event.preventDefault(); const data = new FormData(event.target); const username = String(data.get('username') || '').trim().toLowerCase(); const password = String(data.get('password') || ''); const user = CRM_DEMO_USERS[username]; const error = document.querySelector('#pdcrm-login-error'); if (!user || user.password !== password) { error.textContent = 'Usuario o clave demo incorrectos.'; return; } crmSession = { username, role: user.role, label: user.label, name: user.name, initials: user.initials }; saveSession(crmSession); window.location.href = defaultRouteForRole(user.role); return; } if (event.target.id === 'pdcrm-reception-form') { event.preventDefault(); handleReceptionFormAction(event.submitter?.value || 'next'); return; } if (event.target.id === 'pdcrm-quote-form') { event.preventDefault(); saveQuoteFromForm(event.target, event.submitter?.value || 'save'); return; } if (event.target.id === 'pdcrm-order-form') { event.preventDefault(); const data = new FormData(event.target); const client = crmClient(data.get('clientId')); if (!data.get('clientId') || !data.get('reportedIssue')) return showCrmToast('Completa cliente y problema reportado.', 'error'); const order = { id: `OS-${String(crmState.orders.length + 19).padStart(3, '0')}`, quoteId: null, clientId: client.id, vehicleId: client.id, status: 'nueva', reportedIssue: data.get('reportedIssue'), dateReceived: data.get('dateReceived') || crmDate(), responsible: data.get('responsible'), estimate: Number(data.get('estimate')) || 0, updated: 'Ahora', notes: data.get('notes'), items: [{ type: 'Servicio', description: 'Pendiente de definir', quantity: 1, price: Number(data.get('estimate')) || 0 }] }; crmState.orders.unshift(order); addActivity('order', `${order.id} creada`, `${client.name} · ahora`, `/crm/ordenes/${order.id}`); saveCrmState(); navigateCrm(`/crm/ordenes/${order.id}`); showCrmToast('Nueva orden demo guardada.'); } }
function initCrmDemo() { document.body.className = 'crm-body'; crmState = loadCrmState(); crmSession = loadSession(); document.title = 'PD-054 · CRM demo'; window.addEventListener('popstate', renderCrm); renderCrm(); }
if (isCrmRoute()) initCrmDemo();
